insert into public.modules (id, slug, title, description, category_id, module_number, status, difficulty, duration_minutes, audience, teams, tags, needs_claim_review, published_at) values
  ('5fbcccf1-db33-52cc-a92e-dcdc3504fef8', 'chat-etiquette', 'Chat Etiquette', 'The 22 chat rules: greeting, response time, tone, emoji discipline, confirmations, and complaint handling.', '1e1fb7c1-f3f4-583c-9a84-0efc7eb68854', 3, 'published', 'foundation', 40, array['sales', 'admin']::public.user_role[], array['Chat Support', 'Phone Sales']::text[], array['chat', 'etiquette', 'messenger', 'foundation']::text[], false, now())
on conflict (id) do update set
