insert into public.lessons (id, module_id, title, summary, sort_order, status) values
  ('377b0fd6-718d-5fa6-b170-c18427a15410', '7ee94025-2414-5db6-a733-cadbdfb4809c', 'An Objection Is Not a Rejection', 'A customer who objects is still in the conversation.', 0, 'published'),
  ('e23a57e8-5d2d-5562-b599-e38ef7ad60d4', '7ee94025-2414-5db6-a733-cadbdfb4809c', 'The A.C.A.C. Formula', 'Four moves that work on all twelve objections.', 1, 'published'),
  ('9f03023c-4d5d-5181-b62a-a67381a9613b', '7ee94025-2414-5db6-a733-cadbdfb4809c', 'Claims, Earnings, and What You Must Not Promise', 'Read this before you answer anything about kita or ROI.', 2, 'published'),
  ('4786a5c6-b09b-59a4-9c55-4c85e7bfb916', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Mahal naman."', 'That is expensive.', 3, 'published'),
  ('841684bd-5655-5352-b609-9828569d8db4', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Baka hindi ko mabenta."', 'I might not be able to sell it.', 4, 'published'),
  ('afdb9a8f-4821-5b97-851f-67dbfcb29973', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Pag-isipan ko muna."', 'Let me think about it first.', 5, 'published'),
  ('101f5744-5356-53c2-aefb-b4d5bbbb372c', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Wala akong experience sa negosyo."', 'I have no business experience.', 6, 'published'),
  ('65307640-b37f-593d-8289-1ca2375230be', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Wala akong physical store."', 'I do not have a physical store.', 7, 'published'),
  ('b26a1fe1-f560-5e2d-8729-a099bb0ed31a', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Marami nang nagbebenta ng Kangkong Chips."', 'A lot of people already sell Kangkong Chips.', 8, 'published'),
  ('bb17395e-f1f1-5a1c-83c7-ee18d4d1b66b', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"May supplier na ako."', 'I already have a supplier.', 9, 'published'),
  ('7fc9c600-19da-5964-9e43-005a6c01e3a9', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Wala akong malaking capital."', 'I do not have a lot of capital.', 10, 'published'),
  ('4f744929-9503-519b-8874-4c0bad3dfdd0', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Baka matagal ang ROI."', 'The return on investment might take a long time.', 11, 'published'),
  ('a6e4a18d-23d6-5269-a482-714d96c19709', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Hindi ako marunong mag-online selling."', 'I do not know how to sell online.', 12, 'published'),
  ('fe59a7c6-ce64-5d20-a09c-24ecc1927411', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Baka hindi patok sa lugar namin."', 'It might not be popular in our area.', 13, 'published'),
  ('10aeec61-ac78-5b5b-ad2b-9a99309a189f', '7ee94025-2414-5db6-a733-cadbdfb4809c', '"Magkano ang kita ko?"', 'How much will I earn?', 14, 'published')
on conflict (id) do update set
  module_id = excluded.module_id,
  title = excluded.title,
  summary = excluded.summary,
  sort_order = excluded.sort_order,
  status = excluded.status
;

insert into public.content_blocks (id, lesson_id, type, data, sort_order) values
  ('29442c7c-487f-518e-8ea5-9519c5b7a70d', '377b0fd6-718d-5fa6-b170-c18427a15410', 'text', '{"text":"A rejection ends the call. An objection continues it. When a customer says \"mahal naman\", they have already imagined buying - they are telling you what stands between them and the order. Treat it as information, not resistance."}'::jsonb, 0),
  ('1720885c-13ef-5ea9-929e-553c8ee70079', '377b0fd6-718d-5fa6-b170-c18427a15410', 'comparison', '{"caption":"Read the difference","columns":["Objection - keep going","Rejection - close politely"],"rows":[["Mahal naman.","Hindi po ako interesado, salamat."],["Pag-iisipan ko muna.","Please do not contact me again."],["Baka hindi ko mabenta.","Wrong number po."]]}'::jsonb, 1),
  ('a4e6e924-1951-5e9f-a625-86345ed6c714', '377b0fd6-718d-5fa6-b170-c18427a15410', 'callout', '{"variant":"info","title":"When it is a real no","text":"Thank them, leave the door open in one sentence, and end the call. A graceful exit today is a callable lead next quarter."}'::jsonb, 2),
  ('91894f2e-f3dd-5e64-8061-48d0109cb28b', 'e23a57e8-5d2d-5562-b599-e38ef7ad60d4', 'formula', '{"name":"A.C.A.C.","steps":[{"key":"A","label":"Acknowledge","detail":"Validate the concern in one sentence. You are agreeing that it is reasonable to ask - not agreeing that it ends the deal."},{"key":"C","label":"Clarify","detail":"Ask one question to find the specific version of the objection. \"Mahal\" versus budget and \"mahal\" versus a competitor need different answers."},{"key":"A","label":"Address","detail":"Answer the specific concern you just uncovered. Two or three sentences, no product dump."},{"key":"C","label":"Close","detail":"Return to a small, dated next step. Never leave the objection hanging in silence."}]}'::jsonb, 0),
  ('b8004186-4804-53fd-a56f-27997d744e50', 'e23a57e8-5d2d-5562-b599-e38ef7ad60d4', 'callout', '{"variant":"warning","title":"Clarify is the step people skip","text":"Jumping straight from Acknowledge to Address means you are answering the generic objection instead of theirs. One question changes the entire response."}'::jsonb, 1),
  ('072a4e36-93b4-5732-843a-947cca7d9f4b', 'e23a57e8-5d2d-5562-b599-e38ef7ad60d4', 'dosdonts', '{"dos":["Slow down and let them finish","Use their own words back","Ask one clarifying question"],"donts":["Answer before you understand","Discount to escape","Argue that the concern is wrong"]}'::jsonb, 2),
  ('31675d10-76de-5444-b220-07200f0d0879', '9f03023c-4d5d-5181-b62a-a67381a9613b', 'callout', '{"variant":"danger","title":"Never guarantee a business outcome","text":"You may not promise income, a payback period, or that stock will sell. These depend entirely on the customer’s own price, area, and effort. Any number you use is an illustration built from their assumptions, and must be described that way out loud."}'::jsonb, 0),
  ('eedaaad6-f459-55dc-b9c7-5b7b068fb7bf', '9f03023c-4d5d-5181-b62a-a67381a9613b', 'wording', '{"pairs":[{"avoid":"Kikita ka ng ₱20,000 in one month.","use":"Ang kita po ay depende sa selling price niyo - gusto niyo po bang i-compute natin base sa numbers niyo?","note":"Guaranteed figures are prohibited."},{"avoid":"Sigurado pong mabenta yan sa inyo.","use":"Kaya po mababa ang minimum namin - para ma-test niyo muna ang area niyo."},{"avoid":"Two weeks lang, balik na ang puhunan.","use":"Hindi po namin kayang mangako ng specific na panahon - depende po ito sa bilis ng benta niyo."}]}'::jsonb, 1),
  ('0e9bb92a-4a26-5aa4-9832-c7dad248a1ee', '9f03023c-4d5d-5181-b62a-a67381a9613b', 'text', '{"text":"Three cards in this module are flagged as claim-sensitive: \"Baka matagal ang ROI\", \"Baka hindi patok sa lugar namin\", and \"Magkano ang kita ko?\". Those cards carry a visible notice, and any change to their wording goes through Admin review before publishing."}'::jsonb, 2),
  ('5df435b3-080f-54fe-bdc9-f1a176e6db87', '4786a5c6-b09b-59a4-9c55-4c85e7bfb916', 'text', '{"text":"Price objection · heard very high. In English: \"That is expensive.\""}'::jsonb, 0),
  ('d29c488e-a4f8-5f4a-8492-f21ff22aadfa', '4786a5c6-b09b-59a4-9c55-4c85e7bfb916', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"I understand po. Importante talaga na sulit ang bawat piso, especially kung negosyo ang pag-uusapan."},{"key":"C","label":"Clarify","detail":"May I ask - mahal po ba compared sa budget niyo ngayon, or compared sa ibang supplier na nakita niyo?"},{"key":"A","label":"Address","detail":"Kung budget po ang concern: ang starter pack ang pinakamaliit na order namin, kaya mababa ang unang commitment niyo. Kung comparison po sa iba: ang presyo namin ay kasama na ang delivery sa Metro Manila, ang packaging na ready for resale, at ang marketing materials na pwede niyo agad gamitin. Hindi lang po chips ang binabayaran niyo - kasama na ang support para makapagsimula kayo."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-compute natin ang per-pack cost para makita niyo kung saan papasok ang selling price niyo?"}]}'::jsonb, 1),
  ('31d0c18c-220d-5c94-89c7-cd27ace8e925', '4786a5c6-b09b-59a4-9c55-4c85e7bfb916', 'bullets', '{"items":["Do not immediately offer a discount - you probably cannot authorise it, and it teaches the customer to wait for one.","Do not argue that it is \"not expensive\". You are telling them their judgement is wrong.","Do not compare KCO to a named competitor."]}'::jsonb, 2),
  ('be6db79c-be68-5c88-83d0-bb0d6ea2b5f2', '841684bd-5655-5352-b609-9828569d8db4', 'text', '{"text":"Risk objection · heard very high. In English: \"I might not be able to sell it.\""}'::jsonb, 0),
  ('c2fc02f7-78a4-5b5e-bf1b-8d2d405b86d4', '841684bd-5655-5352-b609-9828569d8db4', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Valid po yan, Ms. Rivera. Normal lang mag-alala sa unang order - ayaw naman po natin ma-stuck kayo sa stock."},{"key":"C","label":"Clarify","detail":"May I ask po - ano ang mas kinakabahan niyo, ang paghahanap ng buyers or ang dami ng stock?"},{"key":"A","label":"Address","detail":"Dahil dyan po kami nag-set ng mababang minimum. Sa starter pack, sapat lang po para ma-test niyo kung aling flavour ang mabilis mauubos sa area niyo, hindi yung malaking stock na mahirap ilipat. Bibigyan din po namin kayo ng product photos, captions, at basic selling guide para hindi kayo magsimula sa zero. At kung nauubos po agad, mabilis lang ang resupply."},{"key":"C","label":"Close","detail":"Gusto niyo po bang simulan natin sa pinakamaliit na pack, para test muna, then dagdagan natin pag okay na?"}]}'::jsonb, 1),
  ('270a398b-a750-50b9-acd3-9064b2a18282', '841684bd-5655-5352-b609-9828569d8db4', 'bullets', '{"items":["Never promise that the stock will definitely sell.","Do not dismiss the fear - it is the most reasonable objection on this list.","Do not push a larger pack to hit a quota."]}'::jsonb, 2),
  ('7cd28451-6453-5671-9eb4-0238c70c9449', 'afdb9a8f-4821-5b97-851f-67dbfcb29973', 'text', '{"text":"Timing objection · heard very high. In English: \"Let me think about it first.\""}'::jsonb, 0),
  ('19ddbf45-5065-59cc-b7bb-81ebcf689a78', 'afdb9a8f-4821-5b97-851f-67dbfcb29973', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Of course po - dapat lang na pag-isipan ang anumang investment. Take your time."},{"key":"C","label":"Clarify","detail":"May I ask lang po, para matulungan ko kayo - ano pong part ang pinag-iisipan niyo? Yung presyo, yung pagbebenta, or kailangan niyo pang kausapin ang partner niyo?"},{"key":"A","label":"Address","detail":"Kung presyo po: pwede natin i-break down ang cost per pack. Kung pagbebenta po: may guide kami kung paano magsimula online. Kung may kausapin pa po kayo, i-send ko na lang ang complete details para may maipakita kayo - kasama na ang inclusions at delivery schedule."},{"key":"C","label":"Close","detail":"I-send ko po ang details ngayon. Pwede po ba akong mag-follow up bukas ng hapon para sagutin ang mga tanong niyo?"}]}'::jsonb, 1),
  ('5ad5a6ff-5cf3-5cf6-8bcb-bfb8feca836e', 'afdb9a8f-4821-5b97-851f-67dbfcb29973', 'bullets', '{"items":["Do not ask \"why?\" bluntly - it reads as a challenge.","Do not invent urgency (\"last stock na po\") that is not real.","Do not ask for the sale again in the same breath."]}'::jsonb, 2),
  ('b8b11e3c-8b1a-5cc9-8d1c-0d5872dc8270', '101f5744-5356-53c2-aefb-b4d5bbbb372c', 'text', '{"text":"Capability objection · heard high. In English: \"I have no business experience.\""}'::jsonb, 0),
  ('41b14378-ba60-50dc-9a86-3f9de71c170a', '101f5744-5356-53c2-aefb-b4d5bbbb372c', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Naiintindihan ko po. Marami sa mga reseller namin ay first-timers din nung nagsimula sila."},{"key":"C","label":"Clarify","detail":"May I ask po - nakapag-sell na po ba kayo online kahit personal items lang, or talagang first time?"},{"key":"A","label":"Address","detail":"Hindi po kailangan ng business background para dito. Ang binibigay namin ay ang produkto, ang product photos, ready-to-use captions, at isang simpleng guide kung paano mag-post at sumagot sa tanong ng customer. Ang kailangan lang po sa umpisa ay isang Facebook account at willingness mag-reply sa mga tanong. Meron din po kaming reseller support kung may hindi kayo sigurado."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-send ko yung starter guide para makita niyo mismo kung gaano kasimple ang proseso?"}]}'::jsonb, 1),
  ('a3f598e9-7794-57ae-a237-269ddd3a663a', '101f5744-5356-53c2-aefb-b4d5bbbb372c', 'bullets', '{"items":["Do not say \"madali lang yan\" - it minimises a real worry.","Do not promise hand-holding that the team cannot actually deliver."]}'::jsonb, 2),
  ('576e4d40-4c68-5e7c-a98f-4899d27f883c', '65307640-b37f-593d-8289-1ca2375230be', 'text', '{"text":"Capability objection · heard high. In English: \"I do not have a physical store.\""}'::jsonb, 0),
  ('9c2a6c55-e4ba-5a56-92fd-ce160624eaf7', '65307640-b37f-593d-8289-1ca2375230be', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Okay lang po yan - hindi po requirement ang physical store para maging KCO reseller."},{"key":"C","label":"Clarify","detail":"May I ask po - active po ba kayo sa Facebook or Messenger? Yun po ang pinakamadaling simulan."},{"key":"A","label":"Address","detail":"Malaking parte po ng mga reseller namin ay online lang - Facebook posts, Messenger orders, at meet-up or delivery. Walang rent, walang display shelf. Bibigyan po namin kayo ng photos at captions na pwede niyo agad i-post, at may packaging na kayang i-ship. Kung may sari-sari store naman po ang kakilala niyo, pwede rin kayo mag-supply sa kanila."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-set up natin ang online starter pack para sa inyo?"}]}'::jsonb, 1),
  ('11bcecfa-da82-5629-b87b-b19ced3c978c', '65307640-b37f-593d-8289-1ca2375230be', 'bullets', '{"items":["Do not imply an online seller is a lesser reseller.","Do not promise delivery coverage you have not checked."]}'::jsonb, 2),
  ('15778994-8205-5f27-bd07-4aedde61d2c3', 'b26a1fe1-f560-5e2d-8729-a099bb0ed31a', 'text', '{"text":"Competition objection · heard high. In English: \"A lot of people already sell Kangkong Chips.\""}'::jsonb, 0),
  ('842af64e-9053-51d1-866e-c233375335ee', 'b26a1fe1-f560-5e2d-8729-a099bb0ed31a', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Tama po kayo - sumikat talaga ang kangkong chips, kaya marami ang nag-offer."},{"key":"C","label":"Clarify","detail":"May I ask po - nakita niyo po ba kung ano ang binebenta nila sa area niyo, at magkano?"},{"key":"A","label":"Address","detail":"Dalawa po ang pinag-iba namin. Isa, ang produkto: consistent ang crunch at packaging namin, at may proper labeling - hindi repacked. Dalawa, ang support: bibigyan namin kayo ng marketing materials at reseller pricing na hindi lang basta paubos ng stock. Ang mataas na demand po ay hindi problema - ibig sabihin may market na. Ang mahalaga ay kayo ang may maayos na supply at presentation."},{"key":"C","label":"Close","detail":"Gusto niyo po bang ipakita ko ang product photos at packaging namin para makita niyo ang difference?"}]}'::jsonb, 1),
  ('329241de-00c1-54da-8005-1652a9988371', 'b26a1fe1-f560-5e2d-8729-a099bb0ed31a', 'bullets', '{"items":["Never disparage a named competitor or another reseller.","Do not claim exclusivity or territory rights unless Admin has confirmed them in writing."]}'::jsonb, 2),
  ('09f90457-8929-5820-9477-de793f1e2478', 'bb17395e-f1f1-5a1c-83c7-ee18d4d1b66b', 'text', '{"text":"Competition objection · heard medium. In English: \"I already have a supplier.\""}'::jsonb, 0),
  ('6d86417a-0a4c-55ff-8f53-04eadfdbfd24', 'bb17395e-f1f1-5a1c-83c7-ee18d4d1b66b', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Mabuti po yan - ibig sabihin alam niyo na ang proseso ng pag-resupply."},{"key":"C","label":"Clarify","detail":"May I ask po - kumusta ang supply nila, consistent po ba ang stock at delivery?"},{"key":"A","label":"Address","detail":"Hindi po namin kailangang palitan ang supplier niyo agad. Ang ginagawa ng ibang reseller ay ginagamit kami as backup - pag out of stock sila or delayed ang delivery, may mapupuntahan kayo agad. Kung mas okay naman po ang terms namin sa tagal ng panahon, kayo na po ang magdedesisyon. Walang exclusivity requirement po sa amin."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-send ko ang pricing namin para may comparison kayo, kahit for reference lang muna?"}]}'::jsonb, 1),
  ('c5ff81d4-98fb-574b-9047-5543847251f5', 'bb17395e-f1f1-5a1c-83c7-ee18d4d1b66b', 'bullets', '{"items":["Do not ask them to break an existing agreement.","Do not ask who their supplier is - it reads as intelligence-gathering.","Do not undercut with a price you cannot honour."]}'::jsonb, 2),
  ('b85bd802-ed88-540f-bfaf-10ffcb1fcf00', '7fc9c600-19da-5964-9e43-005a6c01e3a9', 'text', '{"text":"Capital objection · heard very high. In English: \"I do not have a lot of capital.\""}'::jsonb, 0),
  ('15a91f74-5a97-5dbf-b10d-1b5610710d61', '7fc9c600-19da-5964-9e43-005a6c01e3a9', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Naiintindihan ko po. Hindi po biro ang maglabas ng pera para sa panibagong negosyo."},{"key":"C","label":"Clarify","detail":"May I ask po - magkano ang comfortable niyong ilabas sa unang order, para makita natin kung kasya?"},{"key":"A","label":"Address","detail":"Dahil dyan po ang starter pack ang pinakamababang entry namin - yun po ang minimum na order, hindi yung malaking bulk. Ganun din po ang dahilan kung bakit kasama na ang delivery sa Metro Manila, para walang dagdag na gastos sa umpisa. Wala rin pong franchise fee, membership fee, o bayad sa marketing materials."},{"key":"C","label":"Close","detail":"Gusto niyo po bang tignan natin ang exact na halaga ng starter pack, para malaman niyo kung kasya sa budget niyo ngayon?"}]}'::jsonb, 1),
  ('690dc0ef-9a02-52cf-afcf-eb505051d408', '7fc9c600-19da-5964-9e43-005a6c01e3a9', 'bullets', '{"items":["Never suggest borrowing money or offering a loan.","Do not present the purchase as risk-free.","Do not quote an instalment scheme unless Finance has approved one in writing."]}'::jsonb, 2),
  ('a2ef3c86-1680-597c-b6dd-8007873fed21', '4f744929-9503-519b-8874-4c0bad3dfdd0', 'text', '{"text":"Risk objection · heard medium. In English: \"The return on investment might take a long time.\""}'::jsonb, 0),
  ('795dcf7e-a7d6-5485-850e-5269df162056', '4f744929-9503-519b-8874-4c0bad3dfdd0', 'callout', '{"variant":"danger","title":"Claim-sensitive - illustrative only","text":"This response touches earnings or market performance. Present every figure as the customer’s own example, never as a guaranteed result. Wording changes require Admin review."}'::jsonb, 1),
  ('96ee3d13-3b14-5364-a3fc-2be2585f2dee', '4f744929-9503-519b-8874-4c0bad3dfdd0', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Magandang tanong po - dapat lang alam niyo kung kailan bumabalik ang pera niyo."},{"key":"C","label":"Clarify","detail":"May I ask po - ilan ang customer na kayang maabot niyo sa isang linggo, at gaano kadalas kayo makakapag-post?"},{"key":"A","label":"Address","detail":"Maging prangka po tayo: depende po ito sa selling price na ilalagay niyo, sa area niyo, at kung gaano kadalas kayo mag-post o mag-alok. Hindi po namin kayang mangako ng specific na panahon. Ang kaya po naming gawin ay tulungan kayong makuha ang tamang selling price at bigyan kayo ng materials para mas mabilis mag-move ang stock. Kung gusto niyo po, i-compute natin ang break-even base sa sarili niyong numbers - pero example lang po ito, hindi guarantee."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-compute natin nang sabay ang break-even base sa target selling price niyo?"}]}'::jsonb, 2),
  ('20ba20c3-1f4a-5c59-b0f9-5069849898c4', '4f744929-9503-519b-8874-4c0bad3dfdd0', 'bullets', '{"items":["Never state or imply a guaranteed payback period.","Never quote a \"typical\" ROI figure that Admin has not approved.","Always label any computation as an illustration built from the customer’s own assumptions."]}'::jsonb, 3),
  ('9f09ca70-55f3-506e-ba86-9311edc182ec', 'a6e4a18d-23d6-5269-a482-714d96c19709', 'text', '{"text":"Capability objection · heard high. In English: \"I do not know how to sell online.\""}'::jsonb, 0),
  ('2423ecb3-87fd-5bb3-889b-146226b90280', 'a6e4a18d-23d6-5269-a482-714d96c19709', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Okay lang po yan. Marami sa nagsisimula ay ganun din - natutunan lang nila habang nag-post."},{"key":"C","label":"Clarify","detail":"May I ask po - gumagamit po ba kayo ng Facebook or Messenger sa araw-araw?"},{"key":"A","label":"Address","detail":"Kung marunong po kayong mag-post at mag-reply sa Messenger, sapat na po yun para makapagsimula. Bibigyan po namin kayo ng ready na product photos, captions na pwede niyong kopyahin, at simpleng guide kung paano sagutin ang mga karaniwang tanong - presyo, delivery, at flavour. Hindi po kailangan ng website, ads, o technical na kaalaman sa umpisa."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-send ko yung starter kit ng photos at captions para makita niyo?"}]}'::jsonb, 1),
  ('e74e5132-46dc-5de7-9c5a-55830d602535', 'a6e4a18d-23d6-5269-a482-714d96c19709', 'bullets', '{"items":["Do not overwhelm them with ads, SEO, or marketplace jargon.","Do not promise training sessions that do not exist."]}'::jsonb, 2),
  ('05089e30-016c-5afb-a951-5223baef2bc5', 'fe59a7c6-ce64-5d20-a09c-24ecc1927411', 'text', '{"text":"Market objection · heard medium. In English: \"It might not be popular in our area.\""}'::jsonb, 0),
  ('65c20fd4-437d-59e7-882d-f33f1ef2df58', 'fe59a7c6-ce64-5d20-a09c-24ecc1927411', 'callout', '{"variant":"danger","title":"Claim-sensitive - illustrative only","text":"This response touches earnings or market performance. Present every figure as the customer’s own example, never as a guaranteed result. Wording changes require Admin review."}'::jsonb, 1),
  ('37c75d8a-781e-5825-ba04-0077039ba6fd', 'fe59a7c6-ce64-5d20-a09c-24ecc1927411', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Fair po yan - magkaiba talaga ang nagpapatok sa bawat lugar."},{"key":"C","label":"Clarify","detail":"May I ask po - saan po banda kayo, at ano ang uso pong snack sa area niyo ngayon?"},{"key":"A","label":"Address","detail":"Ang pinakamurang paraan po para malaman ay maliit na test order. Yun ang dahilan kung bakit mababa ang minimum namin - para hindi kayo mag-commit sa malaking stock bago malaman kung tatanggapin sa area niyo. Nakakatulong din po na healthier snack ang positioning ng kangkong chips, kaya kadalasan may market sa mga school, office, at sari-sari store. Pero test order po ang magsasabi, hindi ang assumption natin."},{"key":"C","label":"Close","detail":"Gusto niyo po bang simulan sa isang starter pack as test para sa area niyo?"}]}'::jsonb, 2),
  ('d3a418e8-530b-5cce-80c1-32e15ccf36d5', 'fe59a7c6-ce64-5d20-a09c-24ecc1927411', 'bullets', '{"items":["Do not claim the product \"always sells\" anywhere.","Do not cite sales figures from another area as a promise."]}'::jsonb, 3),
  ('87231546-ae44-52c5-aa38-37321ba33d4b', '10aeec61-ac78-5b5b-ad2b-9a99309a189f', 'text', '{"text":"Price objection · heard very high. In English: \"How much will I earn?\""}'::jsonb, 0),
  ('71161d4b-180b-5127-9ecc-72a2d440f3d0', '10aeec61-ac78-5b5b-ad2b-9a99309a189f', 'callout', '{"variant":"danger","title":"Claim-sensitive - illustrative only","text":"This response touches earnings or market performance. Present every figure as the customer’s own example, never as a guaranteed result. Wording changes require Admin review."}'::jsonb, 1),
  ('8604d079-b027-5854-861b-0cffdbd65f91', '10aeec61-ac78-5b5b-ad2b-9a99309a189f', 'formula', '{"name":"A.C.A.C. response","steps":[{"key":"A","label":"Acknowledge","detail":"Magandang tanong po - dapat lang malinaw ito bago kayo mag-order."},{"key":"C","label":"Clarify","detail":"May I ask po - magkano ang balak niyong ipagbenta per pack sa area niyo?"},{"key":"A","label":"Address","detail":"Ang kita po ay ang pagitan ng reseller price niyo at ng selling price na ilalagay niyo, less ang gastos niyo sa delivery o packaging. Ibibigay po namin ang exact reseller price at ang suggested retail range, pero kayo po ang magdedesisyon sa final selling price niyo. Hindi po namin kayang mangako ng specific na kita - nakadepende po ito sa presyo niyo, sa dami ng mabebenta, at sa area niyo."},{"key":"C","label":"Close","detail":"Gusto niyo po bang i-compute natin ang margin base sa selling price na naiisip niyo, para may malinaw kayong number?"}]}'::jsonb, 2),
  ('90599b2e-8a34-5412-a6d9-6db794a93943', '10aeec61-ac78-5b5b-ad2b-9a99309a189f', 'bullets', '{"items":["Never guarantee an income figure, monthly or otherwise.","Never repeat another reseller’s earnings as an expected result.","Always frame computations as the customer’s own numbers, clearly marked as an example."]}'::jsonb, 3)
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  type = excluded.type,
  data = excluded.data,
  sort_order = excluded.sort_order
;


