  ('7925a399-92cf-5df4-8141-a93febf41e7c', 'training-activities', 'Training Activities', 'Eight facilitator-led exercises, matched to the specific habit each one fixes.', 'e0f82390-0ad6-519b-9e95-a7c35d3ab972', 6, 'published', 'intermediate', 30, array['admin', 'sales']::public.user_role[], array['Training', 'Phone Sales', 'Chat Support']::text[], array['activities', 'facilitation', 'huddle', 'roleplay']::text[], false, now())
