insert into public.learning_paths (id, slug, title, description, audience, accent, status, published_at) values
  ('5ca7b984-b5dc-5acb-9812-791c6e9a2772', 'new-hire-foundation', 'New Hire Foundation', 'The first week. Everything a new KCO agent needs before taking a live call or chat on their own.', array['sales']::public.user_role[], 'green', 'published', now()),
  ('afa85750-45ef-5736-b3a0-ac2e214953a9', 'chat-support-specialist', 'Chat Support Specialist', 'For agents working the Messenger queue full time - etiquette, the G.A.L.P.H.C.F.R. formula, and written objection handling.', array['sales']::public.user_role[], 'blue', 'published', now()),
  ('31962445-e608-57b2-8b5d-14149b78506c', 'closing-and-objections', 'Closing & Objections', 'For agents who open well but stall at the close. Structure, A.C.A.C., and the twelve objection cards.', array['sales']::public.user_role[], 'amber', 'published', now()),
  ('9c1f27f6-6e54-59bc-96cc-ad6c9ebd464f', 'facilitator-track', 'Facilitator Track', 'For team leads running huddles: how to pick, run, and debrief the eight training activities.', array['admin']::public.user_role[], 'rose', 'published', now())
