insert into public.assessments (id, slug, title, description, module_id, passing_score, time_limit_minutes, attempts_allowed, status, published_at) values
  ('d904d1a1-a8cc-5ab7-b45c-320901bdf401', 'phone-etiquette-check', 'Phone Etiquette Check', 'Six questions on greeting, hold, recovery, and what you may never invent.', '2e397237-467e-5050-a02a-677dbd0dab8d', 80, 10, 3, 'published', now()),
  ('270bc430-0b9b-5995-bc10-307da96f8fd3', 'chat-standards-check', 'Chat Standards Check', 'Response times, tone, confirmations, and the four openers you see every day.', '5fbcccf1-db33-52cc-a92e-dcdc3504fef8', 80, 10, 3, 'published', now()),
  ('7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'objection-handling-certification', 'Objection Handling Certification', 'A.C.A.C. applied under pressure, including the claims you are prohibited from making.', '7ee94025-2414-5db6-a733-cadbdfb4809c', 85, 15, 2, 'published', now()),
  ('7a783bc9-ba3d-5e1f-8bb2-38199a0358a4', 'professional-wording-drill', 'Professional Wording Drill', 'Quick swaps - the casual phrase in, the professional version out.', '1c917f14-e30e-5b9b-9cec-96227a26e9a9', 75, 5, 5, 'published', now())
on conflict (id) do update set
