;

insert into public.assessment_questions (id, assessment_id, type, prompt, explanation, points, sort_order) values
  ('5636b0d5-0471-52eb-aa53-4e7c37044830', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'Which opening follows the KCO standard?', 'Time of day, your name, the full company name, and confirmation of who you are speaking with - before anything about the offer.', 1, 0),
  ('fe579c91-cf19-56c6-9531-7e66af902d22', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'A customer needs to be placed on hold. What must happen first?', 'Ask, explain, estimate - then beat the estimate and thank them on return.', 1, 1),
  ('8bd2dbb6-9255-58a9-b84a-9295a10e7acc', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'The call drops mid-conversation. Who calls back, and what do you do?', 'The agent always owns the callback, and resuming - not restarting - respects the customer’s time.', 1, 2),
  ('9c153f4a-a926-5b58-ad4f-d2b91e057d99', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'You do not know the exact shelf life of the product. What do you say?', 'Never invent a product fact. Commit to verifying, attach a time, and follow through.', 1, 3),
  ('0920a9cc-e1e4-5bf3-a462-ec7d2348f89f', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'A customer says "Sorry, busy ako ngayon." What is the correct response?', 'Two specific options get a real commitment; "anytime" gets nothing. Then log the callback and honour it.', 1, 4),
  ('0b3dedd8-9170-586c-b648-25fd2b1ee5c6', 'd904d1a1-a8cc-5ab7-b45c-320901bdf401', 'multiple_choice', 'An angry customer is describing a delivery problem. What do you do first?', 'Absorb the first wave without interrupting or defending. Only then acknowledge, commit to an action, and give a deadline.', 1, 5),
  ('ea86ef92-eda7-5488-9f1a-a86d7e838988', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'What is the target first-reply time for a new chat?', 'Two minutes for a first reply; one minute inside an active conversation.', 1, 0),
  ('9caa2098-4661-58b5-a217-f41b6b09a11f', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'A customer messages only "Send details po." What is the best reply?', 'One question turns a cold request into a conversation and lets you send something relevant.', 1, 1),
  ('b05527fb-cd89-5b27-887a-573be5d4ecef', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'Which message meets the KCO chat standard?', 'Answer, add a useful detail, hand back a question - with proper capitalisation and no text-speak.', 1, 2),
  ('bcd4a130-5899-5a97-a27e-274d1a57219a', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'When should you avoid emoji entirely?', 'Emoji soften friendly messages and undermine serious ones. Drop them when a customer is upset or money is disputed.', 1, 3),
  ('f830c054-dbf7-5f4a-bb08-5d1580f38eba', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'How many follow-ups may you send to an unresponsive lead?', 'Two maximum, and each must add something useful. After that, log the lead as cold and stop.', 1, 4),
  ('2b25c2d9-f7fc-5a31-9fcb-89e829e7d7d9', '270bc430-0b9b-5995-bc10-307da96f8fd3', 'multiple_choice', 'Which item is NOT required in an order confirmation message?', 'Supplier identity is confidential company information and never appears in a customer-facing message.', 1, 5),
  ('1b8e7954-91b7-5e0c-a7c7-ed2c72decb18', '7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'multiple_choice', 'What does the second letter of A.C.A.C. stand for, and why does it matter?', 'Clarify is the most-skipped step. Without it you answer the generic objection instead of theirs.', 2, 0),
  ('ae43a3c9-1eb3-5cb7-a461-c9a6c59bdbd0', '7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'multiple_choice', 'A customer asks "Magkano ang kita ko?" What may you say?', 'Guaranteed earnings are prohibited. Any computation must be built from the customer’s own assumptions and labelled as an example.', 2, 1),
  ('f3fe5ebd-282d-5e75-8c82-375647033605', '7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'multiple_choice', 'A customer says "May supplier na ako." What is the correct approach?', 'Never ask them to break an agreement, never disparage a competitor, and never undercut with a price you cannot honour.', 2, 2),
  ('091e034c-bc93-5bb3-96f6-019d9e33470a', '7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'multiple_choice', 'Which is an objection rather than a rejection?', 'An objection names a specific obstacle - the customer is still in the conversation. A rejection ends it, and should be accepted gracefully.', 1, 3),
  ('109d2e6c-212c-5369-9067-6fe3ce8d63c1', '7d02cc99-602e-5c80-b104-81f68b3f1eb5', 'multiple_choice', 'A customer says "Mahal naman." Your first move is to:', 'Acknowledge, then clarify. Discounting first teaches customers to wait for one, and arguing tells them their judgement is wrong.', 2, 4),
  ('9d19e5d1-32a8-5e21-81f9-0c44203f13cb', '7a783bc9-ba3d-5e1f-8bb2-38199a0358a4', 'multiple_choice', 'Replace: "Wait lang."', 'Hold is always requested, never instructed.', 1, 0),
  ('94141e05-4306-56ee-93a6-a722b2168394', '7a783bc9-ba3d-5e1f-8bb2-38199a0358a4', 'multiple_choice', 'Replace: "Hindi pwede yan."', 'Every no needs an alternative attached, or the customer has nothing to say yes to.', 1, 1),
  ('a73e7ef7-16af-5dce-b17e-09437c002d85', '7a783bc9-ba3d-5e1f-8bb2-38199a0358a4', 'multiple_choice', 'Replace: "Fault yun ng courier."', 'Never blame a third party by name. Own the next action instead.', 1, 2),
  ('86204656-3b6a-5681-a30a-7aa37b727e04', '7a783bc9-ba3d-5e1f-8bb2-38199a0358a4', 'multiple_choice', 'Replace: "Sure na po yan kikita kayo."', 'Guaranteed earnings are prohibited on every channel.', 2, 3)
on conflict (id) do update set
  assessment_id = excluded.assessment_id,
  type = excluded.type,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  points = excluded.points,
  sort_order = excluded.sort_order
;

insert into public.assessment_choices (id, question_id, text, is_correct, sort_order) values
  ('ea2e246e-eb6d-5bd3-94cd-5affa87e55cc', '5636b0d5-0471-52eb-aa53-4e7c37044830', 'Hello? Sino po ito?', false, 0),
  ('ae50f3b9-aa51-5f90-b036-bc7f62989717', '5636b0d5-0471-52eb-aa53-4e7c37044830', 'Good morning! This is Jason from KCO Kangkong Chips. Am I speaking with Ms. Rivera?', true, 1),
  ('132a040a-f514-57b4-96ff-c0c53430e5cb', '5636b0d5-0471-52eb-aa53-4e7c37044830', 'Hi, calling about the chips inquiry.', false, 2),
  ('105c0e2f-4999-59e4-8c1d-856ea08b336a', '5636b0d5-0471-52eb-aa53-4e7c37044830', 'Good morning, KCO here, we have a promo today.', false, 3),
  ('fbd8b51c-9975-5ea9-945d-6c7381af2b1b', 'fe579c91-cf19-56c6-9531-7e66af902d22', 'Tell them "wait lang po" and mute.', false, 0),
  ('07852693-72b2-5ad6-9bc2-71a4d4786e71', 'fe579c91-cf19-56c6-9531-7e66af902d22', 'Ask permission, say why, and give a time estimate.', true, 1),
  ('c2af529d-d07d-50fa-918f-7af27a3832dc', 'fe579c91-cf19-56c6-9531-7e66af902d22', 'Put them on hold and explain when you return.', false, 2),
  ('02c9fbdf-33ca-5134-93b0-1e64f832dc2a', 'fe579c91-cf19-56c6-9531-7e66af902d22', 'Transfer them to a colleague instead.', false, 3),
  ('ac046d18-0f47-5537-825c-2243177c4493', '8bd2dbb6-9255-58a9-b84a-9295a10e7acc', 'Wait for the customer to call back.', false, 0),
  ('802c5262-2dc5-5800-ae14-a9ba4f2a963d', '8bd2dbb6-9255-58a9-b84a-9295a10e7acc', 'Call back within a minute, apologise briefly, and resume where you stopped.', true, 1),
  ('45046420-ee47-5f53-82c9-4425e509c1f1', '8bd2dbb6-9255-58a9-b84a-9295a10e7acc', 'Call back and restart the pitch from the greeting.', false, 2),
  ('d0ba96cb-d61b-5672-a9d2-59461bb89d72', '8bd2dbb6-9255-58a9-b84a-9295a10e7acc', 'Send a chat message and wait.', false, 3),
  ('3c954da6-fc34-5bc2-9964-2c422e7e4b6d', '9c153f4a-a926-5b58-ad4f-d2b91e057d99', '"Mga 6 months po siguro."', false, 0),
  ('99e2dc70-dd83-5e94-bcee-c82be2cdb9ab', '9c153f4a-a926-5b58-ad4f-d2b91e057d99', '"Hindi ko po alam."', false, 1),
  ('6ecf1a05-f1ad-5dcc-8ff1-254fc63f6a08', '9c153f4a-a926-5b58-ad4f-d2b91e057d99', '"Let me verify that for you and come back to you within the hour."', true, 2),
  ('fe26cd86-25c6-5cab-8b4b-49e33c05e065', '9c153f4a-a926-5b58-ad4f-d2b91e057d99', '"Nasa packaging po yun."', false, 3),
  ('cc30c0f1-d6b9-52ea-8816-fbbec9dc8467', '0920a9cc-e1e4-5bf3-a462-ec7d2348f89f', 'Explain that it will only take a second and continue.', false, 0),
  ('d55be0cc-93d3-53f1-b8fb-4a73ce4964f4', '0920a9cc-e1e4-5bf3-a462-ec7d2348f89f', 'Acknowledge, offer two specific callback times, confirm one, and end the call.', true, 1),
  ('423a8e66-4967-5adf-8329-7b0b7ec1df57', '0920a9cc-e1e4-5bf3-a462-ec7d2348f89f', 'Ask for the sale quickly before they hang up.', false, 2),
  ('f3f00245-c283-5c4e-a176-96a2d77e77b6', '0920a9cc-e1e4-5bf3-a462-ec7d2348f89f', 'Say you will call back anytime and hang up.', false, 3),
  ('38855ec4-d441-5c39-b29d-a826865c90fb', '0b3dedd8-9170-586c-b648-25fd2b1ee5c6', 'Explain the courier’s delivery process.', false, 0),
  ('b0ba7bf0-8fc9-5913-8a67-a730bd7a4a04', '0b3dedd8-9170-586c-b648-25fd2b1ee5c6', 'Let them finish completely without defending anything.', true, 1),
  ('d838d5f0-02a6-509f-be4a-03cd693699f1', '0b3dedd8-9170-586c-b648-25fd2b1ee5c6', 'Offer a replacement immediately.', false, 2),
  ('58528f29-2a89-5cf1-becd-cc3a53eddfc0', '0b3dedd8-9170-586c-b648-25fd2b1ee5c6', 'Transfer them to a supervisor.', false, 3),
  ('c6a7b95f-fba2-5e69-a7a2-4425b76aff7a', 'ea86ef92-eda7-5488-9f1a-a86d7e838988', 'Within 30 seconds', false, 0),
  ('02467f07-e32c-5094-a4b4-70c26cdbe647', 'ea86ef92-eda7-5488-9f1a-a86d7e838988', 'Within 2 minutes', true, 1),
  ('a6939e68-74eb-5013-8d93-bbc00fd1824b', 'ea86ef92-eda7-5488-9f1a-a86d7e838988', 'Within 15 minutes', false, 2),
  ('291e68c8-d920-5dfe-aae1-8de32e4dcd12', 'ea86ef92-eda7-5488-9f1a-a86d7e838988', 'Same day', false, 3),
  ('d04611ef-ff78-505e-b65a-a046718f1ac1', '9caa2098-4661-58b5-a217-f41b6b09a11f', 'Send the full price list and every flavour.', false, 0),
  ('3c00d3f5-c10e-5c6d-80bd-10e33d35d3ce', '9caa2098-4661-58b5-a217-f41b6b09a11f', 'Ask one qualifying question, then send the package that matches.', true, 1),
  ('e226033b-05fc-53db-b8d8-4c75a4a3bd99', '9caa2098-4661-58b5-a217-f41b6b09a11f', 'Reply "Sure po" and wait.', false, 2),
  ('6550e768-cd73-5114-946c-bf419fe06f03', '9caa2098-4661-58b5-a217-f41b6b09a11f', 'Send a link to the page.', false, 3),
  ('b89b5f49-11b2-5ebc-8693-fbee165a3514', 'b05527fb-cd89-5b27-887a-573be5d4ecef', 'wla po eh', false, 0),
  ('bd86701f-b351-55ae-b35e-18bfa006900d', 'b05527fb-cd89-5b27-887a-573be5d4ecef', 'Wala pa po sa ngayon, but restock is next week. Gusto niyo po bang i-reserve ko?', true, 1),
  ('29eff694-e95f-535d-ac0f-0b4f70a3893f', 'b05527fb-cd89-5b27-887a-573be5d4ecef', 'WALA PO STOCK', false, 2),
  ('f6e3c203-e0c9-54a4-a6ce-22293f439038', 'b05527fb-cd89-5b27-887a-573be5d4ecef', 'no', false, 3),
  ('785a9dfc-5582-55ed-9c6d-c3c33b29f3cf', 'bcd4a130-5899-5a97-a27e-274d1a57219a', 'In greetings', false, 0),
  ('024d4146-6870-5e7a-ae75-8b2a7ad2a207', 'bcd4a130-5899-5a97-a27e-274d1a57219a', 'When confirming an order', false, 1),
  ('0f48e525-cd96-57c7-927e-6804f0e3841b', 'bcd4a130-5899-5a97-a27e-274d1a57219a', 'In complaint, refund, or bad-news threads', true, 2),
  ('a6837e6e-063b-5713-8758-74a3d66865f2', 'bcd4a130-5899-5a97-a27e-274d1a57219a', 'Never - always use emoji', false, 3),
  ('506de457-7321-5270-af26-a7d6927a2713', 'f830c054-dbf7-5f4a-bb08-5d1580f38eba', 'As many as needed', false, 0),
  ('8ee39ee4-e95c-573d-882e-0086fefb790a', 'f830c054-dbf7-5f4a-bb08-5d1580f38eba', 'One', false, 1),
  ('873e13ea-3914-56ff-b475-432a87fc16a8', 'f830c054-dbf7-5f4a-bb08-5d1580f38eba', 'Two, each adding value', true, 2),
  ('1267365d-16c7-5c4c-8a57-0d1f43ae5c7d', 'f830c054-dbf7-5f4a-bb08-5d1580f38eba', 'Daily until they reply', false, 3),
  ('c0c096ae-a58e-5762-aecf-305065b80b67', '2b25c2d9-f7fc-5a31-9fcb-89e829e7d7d9', 'Delivery date and payment method', false, 0),
  ('979b3742-8012-588b-a178-2f705197b4a8', '2b25c2d9-f7fc-5a31-9fcb-89e829e7d7d9', 'Quantity, flavour, and total', false, 1),
  ('0fbcee73-f5d3-5c51-8e11-b619e5ab8fa9', '2b25c2d9-f7fc-5a31-9fcb-89e829e7d7d9', 'The name of the supplier who produced the batch', true, 2),
  ('b014b009-2fd9-566d-ac10-c234c71fb0f4', '2b25c2d9-f7fc-5a31-9fcb-89e829e7d7d9', 'Complete delivery address and contact number', false, 3),
  ('06a3f837-9423-55c2-b45c-5622dd3c79f9', '1b8e7954-91b7-5e0c-a7c7-ed2c72decb18', 'Close - because you should always ask for the sale early.', false, 0),
  ('84ec7c11-942c-5f79-a9b7-a0e99bccfd1c', '1b8e7954-91b7-5e0c-a7c7-ed2c72decb18', 'Clarify - because "mahal" against a budget and "mahal" against a competitor need different answers.', true, 1),
  ('9adf9933-3311-53cc-a04a-6a1b13c673de', '1b8e7954-91b7-5e0c-a7c7-ed2c72decb18', 'Confirm - because you need the order details in writing.', false, 2),
  ('0a251040-5546-52ae-a9d4-ac2baaca1aed', '1b8e7954-91b7-5e0c-a7c7-ed2c72decb18', 'Convince - because the customer needs persuading.', false, 3),
  ('ae45683a-3644-51e8-98e8-5b11e0ea9dac', 'ae43a3c9-1eb3-5cb7-a461-c9a6c59bdbd0', 'Quote the average monthly earnings of your top resellers.', false, 0),
  ('cb7173f8-4685-5174-837b-e114508fee58', 'ae43a3c9-1eb3-5cb7-a461-c9a6c59bdbd0', 'Promise they will recover their capital within a month.', false, 1),
  ('fcb2185c-7f24-5a4c-81d2-efe670f95061', 'ae43a3c9-1eb3-5cb7-a461-c9a6c59bdbd0', 'Explain that margin depends on their selling price and offer to compute an example from their own numbers.', true, 2),
  ('70bda899-599e-5ffd-9b30-7687cad079bc', 'ae43a3c9-1eb3-5cb7-a461-c9a6c59bdbd0', 'Say earnings are guaranteed by the company.', false, 3),
  ('dcd4145b-83b3-51f0-b49e-a3098ea3b210', 'f3fe5ebd-282d-5e75-8c82-375647033605', 'Ask who the supplier is so you can compare.', false, 0),
  ('04ab6da3-0454-563b-a6f8-3668ce22108e', 'f3fe5ebd-282d-5e75-8c82-375647033605', 'Offer a price below theirs immediately.', false, 1),
  ('4acc89f0-b29e-5e3e-80fe-ab427f8671fa', 'f3fe5ebd-282d-5e75-8c82-375647033605', 'Acknowledge it, ask how consistent their supply is, and position KCO as a backup with no exclusivity requirement.', true, 2),
  ('41b66e6c-d104-5176-8a7c-e5c2bbaf361b', 'f3fe5ebd-282d-5e75-8c82-375647033605', 'Explain why their supplier is unreliable.', false, 3),
  ('17245395-3a77-59ef-a8b8-b9d4bbcec768', '091e034c-bc93-5bb3-96f6-019d9e33470a', '"Please do not contact me again."', false, 0),
  ('015cb673-372c-555e-8668-15c6250476c3', '091e034c-bc93-5bb3-96f6-019d9e33470a', '"Wrong number po."', false, 1),
  ('ab23e792-a8f2-52eb-88db-948eed2c15ac', '091e034c-bc93-5bb3-96f6-019d9e33470a', '"Baka hindi ko mabenta."', true, 2),
  ('0744afe0-2bde-5763-99a2-b7e9fd580dbe', '091e034c-bc93-5bb3-96f6-019d9e33470a', '"Hindi po ako interesado, salamat."', false, 3),
  ('6aab3d84-4b92-5ec8-8588-784929cace71', '109d2e6c-212c-5369-9067-6fe3ce8d63c1', 'Offer a discount.', false, 0),
  ('cf7eee89-b605-5a45-9de4-e8f2cfaeae66', '109d2e6c-212c-5369-9067-6fe3ce8d63c1', 'Explain that the price is actually reasonable.', false, 1),
  ('214d3cec-f28a-5d1e-aab2-b144c394efd6', '109d2e6c-212c-5369-9067-6fe3ce8d63c1', 'Acknowledge the concern, then ask whether it is expensive against their budget or against another supplier.', true, 2),
  ('cd18e625-5e8e-5991-b9d7-37d0a2fb0755', '109d2e6c-212c-5369-9067-6fe3ce8d63c1', 'Move to a cheaper product immediately.', false, 3),
  ('319846c5-ce8a-5890-b691-e2fd4cc4ad95', '9d19e5d1-32a8-5e21-81f9-0c44203f13cb', 'Hold on.', false, 0),
  ('b8ce39e5-7d7d-5cc2-9e52-3234f0536bdd', '9d19e5d1-32a8-5e21-81f9-0c44203f13cb', 'May I ask you to hold for a moment?', true, 1),
  ('719620ab-66a9-5511-a447-0ee2e29da429', '9d19e5d1-32a8-5e21-81f9-0c44203f13cb', 'Sandali lang po.', false, 2),
  ('883de8a1-7f21-59d9-9b1b-7d4553956948', '9d19e5d1-32a8-5e21-81f9-0c44203f13cb', 'One sec.', false, 3),
  ('c5a14849-4f75-5000-854d-58f50019ecd9', '94141e05-4306-56ee-93a6-a722b2168394', 'That is not possible.', false, 0),
  ('af8c6624-6a17-5d7a-bdbe-b157c3452263', '94141e05-4306-56ee-93a6-a722b2168394', 'What I can do for you instead is…', true, 1),
  ('1f56e14c-15c4-55a3-abf3-a928050b5284', '94141e05-4306-56ee-93a6-a722b2168394', 'Sorry, no.', false, 2),
  ('f2dfa9c6-ae0f-5e1f-909f-d67ae392f943', '94141e05-4306-56ee-93a6-a722b2168394', 'Bawal po yan.', false, 3),
  ('2f4b49c4-8e50-540b-b7d7-18b9763b0797', 'a73e7ef7-16af-5dce-b17e-09437c002d85', 'The courier made a mistake.', false, 0),
  ('fa88120f-1527-545a-9f11-2d2ad638ea91', 'a73e7ef7-16af-5dce-b17e-09437c002d85', 'I am sorry this happened. I am filing it with our logistics team today.', true, 1),
  ('d4ccb667-3eed-53f4-9807-685611007a44', 'a73e7ef7-16af-5dce-b17e-09437c002d85', 'Hindi po namin kasalanan yan.', false, 2),
  ('21f63dbd-885e-538e-b937-9cc5557d67c0', 'a73e7ef7-16af-5dce-b17e-09437c002d85', 'That is a delivery issue, not ours.', false, 3),
  ('c678fc61-c399-5bfa-8694-88e0e4b7cada', '86204656-3b6a-5681-a30a-7aa37b727e04', 'You will definitely earn from this.', false, 0),
  ('5b696176-c357-5994-8167-eb8e7e804985', '86204656-3b6a-5681-a30a-7aa37b727e04', 'Ang kita po ay depende sa selling price at area niyo - pwede natin i-compute base sa numbers niyo.', true, 1),
  ('043c8697-a83c-510d-92a0-3d4fd00e7917', '86204656-3b6a-5681-a30a-7aa37b727e04', 'Most resellers earn well.', false, 2),
  ('74542fa7-7cb8-531e-9d84-220a2f7406a4', '86204656-3b6a-5681-a30a-7aa37b727e04', 'Guaranteed po ang kita.', false, 3)
on conflict (id) do update set
  question_id = excluded.question_id,
  text = excluded.text,
  is_correct = excluded.is_correct,
  sort_order = excluded.sort_order
;


-- ---------------------------------------------------------------------------
-- Training activities
-- ---------------------------------------------------------------------------

insert into public.training_activities (id, slug, title, objective, duration_minutes, participants, difficulty, instructions, facilitator_notes, expected_outcome, materials, tags, status) values
  ('c78553b4-75c7-5cd5-866a-935ec598f5fe', 'dont-say-yes-or-no', 'Don''t Say Yes or No', 'Break the habit of one-word answers and force agents to give complete, useful replies under pressure.', 15, '4-12, in pairs', 'foundation', array['Pair up. One is the customer, one is the agent.', 'The customer asks rapid questions designed to invite yes/no answers - "May stock pa po?", "Pwede COD?", "Mahal ba?"', 'The agent must answer completely without ever using the words yes, no, opo, or hindi.', 'Every complete answer must add one detail and end with a question.', 'Run 90 seconds, then swap roles.', 'Score one point per slip. Lowest score wins the round.']::text[], array['Keep the pace fast - the pressure is the point.', 'Listen for the three-part reply: answer, added detail, question back.', 'Call out good rephrasings out loud so the group hears the pattern.', 'Common failure: agents pause too long searching for words. Tell them a short natural pause beats a wrong word.']::text[], 'Agents stop reflexively answering in one word and start building replies that keep the conversation moving.', '{}', array['chat', 'phone', 'warm-up']::text[], 'published'),
  ('37f3161b-838a-5b3e-80a1-a5076fc4f208', 'sell-it-in-10-seconds', 'Sell It in 10 Seconds', 'Force a sharp, benefit-first pitch by removing every spare second.', 20, '5-15, whole group', 'intermediate', array['Each agent gets 10 seconds to pitch Kangkong Chips to the group.', 'The pitch must include one benefit and one call to action.', 'The facilitator times strictly and cuts off at 10 seconds mid-word.', 'The group votes on the clearest pitch, not the loudest.', 'Second round: same agent, same 10 seconds, but a different audience - a sari-sari store owner, an online seller, a parent.']::text[], array['Cut people off exactly at 10 seconds. The discomfort is the lesson.', 'Watch for feature-dumping - "crunchy, healthy, affordable, three flavours" is a list, not a pitch.', 'The second round is where the learning lands: the same product needs a different angle per audience.']::text[], 'Agents can open with one benefit tied to the listener instead of reciting product features.', '{}', array['phone', 'pitch', 'competitive']::text[], 'published'),
  ('a90811ac-1509-5716-9ef1-ed2cb42b94d2', 'pass-the-sales', 'Pass the Sales', 'Practise picking up a call mid-flow and continuing without restarting the pitch.', 25, '6-12, in a circle', 'intermediate', array['One facilitator plays a single customer for the whole round.', 'Agent 1 starts the call at Step 1 - Greet.', 'On the facilitator’s clap, the next agent continues from exactly where the last one stopped.', 'No restarting, no re-introducing, no repeating information already given.', 'The circle continues until the call reaches Step 8 - Confirm + End.', 'Debrief: where did the thread break, and why?']::text[], array['Clap at awkward moments - mid-objection is the most useful place to hand over.', 'Introduce a detail early (a name, a quantity) and see how many agents remember it.', 'This mirrors a real inherited chat thread; connect it to Module 3, Section 07.']::text[], 'Agents listen actively even when they are not speaking, and can resume a conversation without making the customer repeat themselves.', '{}', array['phone', 'teamwork', 'listening']::text[], 'published'),
  ('574bdd14-8298-5fe3-b758-7aa749eb2ead', 'customer-acting', 'Customer Acting', 'Build composure against difficult customer personalities before meeting one live.', 30, '4-10, in pairs with rotation', 'intermediate', array['Draw a personality card: Angry, Sleepy, Confused, Cheap, Funny, Seen Zone, Super Curious, or "I''m Busy".', 'The customer plays that personality without telling the agent which card they drew.', 'The agent runs a real call and must adapt in the moment.', 'After three minutes, the agent guesses the personality.', 'Debrief: what tell gave it away, and what did the agent change in response?']::text[], array['Cap the Angry customer at three minutes - it gets heavy quickly.', 'Remind actors to play a personality, not an insult; no personal attacks.', 'The strongest agents change pace and question style, not their script.', 'Pair with Practice Scenarios for solo repetition afterwards.']::text[], 'Agents read customer mood quickly and adjust pace, tone, and question style instead of pushing the same pitch harder.', '{}', array['phone', 'chat', 'roleplay', 'objections']::text[], 'published'),
  ('761fe7b8-2d1d-5274-a986-655b8daf0424', 'bad-accent-bad-sales', 'Bad Accent / Bad Sales', 'Show - by exaggeration - exactly which delivery habits lose a customer, so agents can hear them in themselves.', 20, '5-15, whole group', 'foundation', array['Round 1: each agent deliberately performs the worst possible call - mumbling, rushing, interrupting, reading the script flatly.', 'The group notes every specific mistake they hear.', 'Round 2: the same agent runs the same call properly.', 'The group names the single biggest improvement between the two.']::text[], array['This is a comedy exercise with a serious point - let the laughter happen, then get specific in the debrief.', 'Never mock a real accent. The target is delivery habits: pace, clarity, interruption, monotone.', 'Write the group’s list of "bad habits" on the board and keep it visible for the week.']::text[], 'Agents can name their own worst delivery habit and demonstrate the corrected version on demand.', '{}', array['phone', 'delivery', 'warm-up']::text[], 'published'),
  ('93f82e58-8950-505c-9c51-6976d6b2053b', 'two-truths-one-lie-product', 'Two Truths, One Lie - Product Edition', 'Expose gaps in product knowledge and kill the habit of guessing.', 20, '4-12, whole group', 'foundation', array['Each agent states three claims about KCO Kangkong Chips - two true, one invented.', 'The group votes on which is the lie.', 'The agent reveals the answer and cites where the true facts come from.', 'Any claim nobody can source goes on the "verify with Admin" list.']::text[], array['The "verify" list is the real output of this exercise - send it to Admin afterwards.', 'Watch for confident wrong answers about shelf life, ingredients, and permits; these are the dangerous ones.', 'Connect directly to Module 1, Section 10 - never invent product facts.']::text[], 'Agents know which product facts they can state confidently and which they must verify before answering.', '{}', array['product-knowledge', 'accuracy']::text[], 'published'),
  ('3c4be56d-8fbe-568c-8302-36c30fb057aa', 'movie-trailer-sales-pitch', 'Movie Trailer Sales Pitch', 'Practise storytelling and vocal energy in a low-stakes, memorable format.', 20, '5-12, whole group', 'advanced', array['Each agent pitches Kangkong Chips as a movie trailer - "In a world where merienda is boring…"', 'The pitch must still contain one real product benefit and one real call to action.', 'Maximum 45 seconds.', 'The group votes for the most entertaining and the most persuasive - separately.', 'Debrief on the gap between those two winners.']::text[], array['The split vote is the whole point: entertaining is not the same as persuasive.', 'Use this to talk about energy level - trailer energy is too much for a real call, but flat energy is too little.', 'Best used mid-week, when energy dips.']::text[], 'Agents find a higher, more engaged vocal register and understand where the line between energetic and theatrical sits.', '{}', array['phone', 'energy', 'storytelling']::text[], 'published'),
  ('1eae4780-0553-5788-b9fe-b58a711ff8e9', 'dramatic-sales-pitch', 'Dramatic Sales Pitch', 'Stretch emotional range so a normal call feels effortless by comparison.', 25, '4-10, in pairs', 'advanced', array['Draw an emotion card: heartbroken, triumphant, mysterious, panicked, or deeply sincere.', 'Deliver the full 8-step call in that emotional register.', 'The partner scores whether every step still appeared, despite the drama.', 'Final round: deliver the same call in a normal professional register and compare how easy it feels.']::text[], array['The final normal round is the actual exercise - everything before it is calibration.', 'Check that the eight steps survive; drama often eats Discover and Confirm.', 'Good closing activity for a training day.']::text[], 'Agents control tone deliberately rather than defaulting to a flat register, and the standard call feels comfortable.', '{}', array['phone', 'energy', 'structure']::text[], 'published')
on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  objective = excluded.objective,
  duration_minutes = excluded.duration_minutes,
  participants = excluded.participants,
  difficulty = excluded.difficulty,
  instructions = excluded.instructions,
  facilitator_notes = excluded.facilitator_notes,
  expected_outcome = excluded.expected_outcome,
  materials = excluded.materials,
  tags = excluded.tags,
  status = excluded.status
;


-- ---------------------------------------------------------------------------
-- Practice scenarios
-- ---------------------------------------------------------------------------

insert into public.practice_scenarios (id, slug, title, channel, personality, difficulty, setup, goal, turns, coaching, status) values
  ('9714ea6f-479a-5ed3-b525-61b508b2e174', 'angry-damaged-delivery', 'Crushed Packs on Arrival', 'phone', 'angry', 'advanced', 'Ms. Rivera ordered 50 packs. Six arrived crushed. She has already messaged the page twice with no reply and is now on the phone.', 'Absorb the anger without arguing, commit to a specific action with a deadline, and keep the reseller.', '[{"id":"sc-angry-t1","customer":"Dalawang beses na akong nag-message sa page niyo, walang sumasagot! Anim sa fifty packs, durog lahat. Paano ko ibebenta yan?!","choices":[{"text":"I hear you, Ms. Rivera, and I am sorry this happened. To confirm po - six out of fifty arrived crushed?","verdict":"best","feedback":"Acknowledges the experience and confirms the specific facts without defending anything. This is the correct first move."},{"text":"Ma’am, that is the courier’s handling, hindi po namin kasalanan yan.","verdict":"poor","feedback":"Blaming a third party in the first ten seconds tells the customer nobody will own the problem. Never name the courier."},{"text":"Sorry po. Pwede po ba kayong mag-file ng claim sa courier?","verdict":"poor","feedback":"Pushing the work onto an already-angry customer. KCO files the ticket, not the reseller."}]},{"id":"sc-angry-t2","customer":"Oo, anim. May picture ako. So ano, sagot niyo ba yan o hindi?","choices":[{"text":"Thank you for the photo - malaking tulong po yan sa report. I am filing this with logistics today and I will call you back before 5 PM with the replacement schedule.","verdict":"best","feedback":"Specific action, specific deadline, and the photo is acknowledged as useful rather than demanded as proof."},{"text":"Yes po, ipapalit namin lahat, libre, ngayon din.","verdict":"poor","feedback":"You are not authorised to approve replacements on the spot. Promising one you cannot deliver turns one angry call into two."},{"text":"Kailangan ko po munang i-check sa team. Mag-message na lang po kayo ulit.","verdict":"ok","feedback":"Checking with the team is correct, but the customer must never be the one to follow up. Own the callback and give a time."}]}]'::jsonb, array['Let her finish the first complaint completely - do not defend anything.', 'Acknowledge the specific number: six of fifty.', 'Never blame the courier by name.', 'Give a deadline you can actually meet.']::text[], 'published'),
  ('1d9c9636-ce67-527a-a209-e1ae7581adb2', 'busy-customer-callback', 'Thirty Seconds of Attention', 'phone', 'busy', 'foundation', 'A warm lead who submitted an inquiry yesterday picks up, but is clearly in the middle of something.', 'Secure a specific callback time in under thirty seconds without pitching.', '[{"id":"sc-busy-t1","customer":"Sorry, busy ako ngayon, may kausap ako.","choices":[{"text":"Naku, understood po - I will keep this short. Would it be better if I call you back later today, or tomorrow morning?","verdict":"best","feedback":"Respects the interruption and offers two specific options. \"Anytime\" gets you nothing."},{"text":"Sandali lang po, one minute lang - about sa Kangkong Chips reseller package…","verdict":"poor","feedback":"Pushing through a stated \"busy\" is the fastest way to lose a warm lead. They will not buy from someone who ignores them."},{"text":"Sige po, tawag na lang po kayo kapag free na kayo.","verdict":"poor","feedback":"The agent always owns the callback. Handing it to the customer means it never happens."}]},{"id":"sc-busy-t2","customer":"Bukas na lang, umaga.","choices":[{"text":"Perfect. I will call you at 9 AM tomorrow. Thank you po, Ms. Rivera!","verdict":"best","feedback":"Converts a vague \"umaga\" into a specific time, confirms it, and ends the call quickly."},{"text":"Sige po, bukas ng umaga. Salamat!","verdict":"ok","feedback":"\"Umaga\" is not a time. Without a specific hour you will call when they are busy again."}]}]'::jsonb, array['Do not pitch.', 'Offer two concrete options.', 'Confirm out loud and get off the phone.']::text[], 'published'),
  ('efe60de4-6c6a-5e6f-a3fb-20d5c6b12dc5', 'send-details-cold-inquiry', '"Send Details Po"', 'chat', 'send-details', 'foundation', 'A new page message arrives with three words and no context.', 'Qualify with one question before sending anything, then present the matching package.', '[{"id":"sc-sd-t1","customer":"Send details po","choices":[{"text":"Sure po! 😊 Before I send - are you planning to sell online, sa physical store, or for personal use? Para po ma-send ko yung tamang details.","verdict":"best","feedback":"One qualifying question, a reason for asking, and a friendly tone. This is the G.A.L.P.H.C.F.R. \"Ask\" step."},{"text":"[sends full price list, all flavours, all promos, delivery matrix]","verdict":"poor","feedback":"A generic dump gets skimmed and ignored. You also lose the chance to learn anything about the lead."},{"text":"Sure po.","verdict":"poor","feedback":"A one-word reply that sends nothing and asks nothing. The conversation dies here."}]},{"id":"sc-sd-t2","customer":"Online po, sa FB. First time ko po magtinda.","choices":[{"text":"Perfect po! Since online at first time, the starter pack is the best fit - 50 packs, delivery included sa Metro Manila, plus product photos at captions na pwede niyo agad i-post. Gusto niyo po bang i-reserve ko para sa Friday?","verdict":"best","feedback":"Present tied to their exact answer, followed by a small dated close. Textbook P and C."},{"text":"Okay po. Ito po ang price list namin sa lahat ng packages.","verdict":"ok","feedback":"You asked a good question and then ignored the answer. Recommend one package, not the whole menu."}]}]'::jsonb, array['Ask before you send.', 'One question, not four.', 'Match the package to their answer.']::text[], 'published'),
  ('92f2c55d-c131-5368-bb9b-b914689317f3', 'cheap-customer-price-loop', 'Everything Comes Back to Price', 'objection', 'cheap', 'intermediate', 'The lead has the details and keeps returning to the price no matter what you say.', 'Run A.C.A.C. properly instead of discounting or arguing.', '[{"id":"sc-cheap-t1","customer":"Ang mahal naman po. May mas mura ba kayo?","choices":[{"text":"I understand po. May I ask - mahal po ba compared sa budget niyo, or compared sa ibang supplier na nakita niyo?","verdict":"best","feedback":"Acknowledge then clarify. These are two different objections needing two different answers."},{"text":"Hindi po mahal yan ma’am, sulit po talaga.","verdict":"poor","feedback":"Telling a customer their judgement is wrong. You will not win this argument."},{"text":"Pwede po kitang bigyan ng discount, ma’am.","verdict":"poor","feedback":"You are not authorised to discount, and offering one teaches every future customer to push for it."}]},{"id":"sc-cheap-t2","customer":"Sa budget po. Konti lang talaga pera ko pang-simula.","choices":[{"text":"Naiintindihan ko po. Kaya nga po mababa ang minimum namin - ang starter pack ang pinakamaliit na order, at kasama na ang delivery. Gusto niyo po bang i-compute natin ang per-pack cost para makita niyo kung kasya sa budget niyo?","verdict":"best","feedback":"Addresses the budget version specifically and closes on a small, non-threatening next step."},{"text":"Sige po, pwede kayo mag-hulugan.","verdict":"poor","feedback":"Instalment terms require Finance approval in writing. Never invent payment schemes."},{"text":"Yun na po ang pinakamura naming presyo.","verdict":"ok","feedback":"True but unhelpful - it ends the conversation. Reframe around the low minimum instead."}]}]'::jsonb, array['Do not discount.', 'Clarify which kind of "expensive" this is.', 'Close on a computation, not a plea.']::text[], 'published'),
  ('61dfdbe8-40b6-5bb7-8c51-58fb7a567bea', 'confused-customer-clarity', 'Asking the Same Thing Three Ways', 'chat', 'confused', 'intermediate', 'The lead has read the details but keeps mixing up the minimum order and the price per pack.', 'Simplify without condescending, and confirm understanding before closing.', '[{"id":"sc-conf-t1","customer":"Ay so 200 po lahat? Tapos 50 packs? Pero magkano po yung isa? Nalilito po ako.","choices":[{"text":"No worries po, i-simple ko 😊 ₱200 po ang isang pack. Ang pinakamaliit na order ay 50 packs. So 50 × ₱200 = ₱10,000 po ang total. Malinaw po ba?","verdict":"best","feedback":"Breaks it into one fact per line, shows the arithmetic, and confirms with a question they can answer yes to."},{"text":"Nakalagay po sa details na sinend ko, ma’am.","verdict":"poor","feedback":"Dismissive, and it does not answer the question. The customer will leave."},{"text":"₱200/pack, MOQ 50, total ₱10k po.","verdict":"ok","feedback":"Correct but compressed with jargon - \"MOQ\" means nothing to a first-time reseller who is already confused."}]}]'::jsonb, array['One idea per message.', 'Never say "sabi na sa post".', 'Confirm with a question they can answer.']::text[], 'published'),
  ('28c80de3-5d66-5728-b808-6e9cfae6a4c0', 'seen-zone-follow-up', 'Read, Not Replied', 'chat', 'seen-zone', 'intermediate', 'You sent complete details 24 hours ago. The message shows as seen. Nothing since.', 'Send one follow-up that adds value - and know when to stop.', '[{"id":"sc-seen-t1","customer":"[seen · no reply · 24 hours]","choices":[{"text":"Hi Ms. Rivera! 😊 Following up po. Ito pala yung sample photos na pwede niyo i-post pag nagsimula na kayo. Nandito lang po ako kung may tanong - no rush po.","verdict":"best","feedback":"Adds a genuinely useful asset and explicitly removes pressure. This is what a follow-up is for."},{"text":"Po? 😊","verdict":"poor","feedback":"Adds nothing and reads as nagging. This is the message that gets pages muted."},{"text":"Ma’am, last stock na po ngayon, baka maubos!","verdict":"poor","feedback":"False urgency is prohibited. If it is not literally true, you may not say it."}]},{"id":"sc-seen-t2","customer":"[seen · still no reply · 3 days later]","choices":[{"text":"Send one final message with a genuine update (restock or new flavour), then log the lead as cold.","verdict":"best","feedback":"Two value-adding follow-ups, then stop and report. Exactly what the F and R steps require."},{"text":"Keep messaging every day until they answer.","verdict":"poor","feedback":"This gets the page reported and costs far more than one lost lead."},{"text":"Call their number instead, three times.","verdict":"poor","feedback":"Escalating channels after silence reads as pressure, not service."}]}]'::jsonb, array['A follow-up must add something.', 'Two maximum.', 'No guilt, no false urgency.']::text[], 'published'),
  ('74fabc09-0967-588b-a633-2a36c54bbc6b', 'curious-customer-questions', 'Twenty Questions', 'chat', 'curious', 'advanced', 'An engaged lead who asks detailed questions - including two you cannot answer without checking.', 'Answer what you know, verify what you do not, and still reach a close.', '[{"id":"sc-cur-t1","customer":"Ilang months po ang shelf life? May FDA po ba kayo? Anong oil ang gamit? Pwede po ba mag-request ng sample?","choices":[{"text":"Great questions po 😊 Sample requests - yes, let me check availability for your area. Sa shelf life at FDA documentation, I want to give you the exact details, so let me verify with our team and send them to you today. Ano po pala ang area niyo, para ma-check ko agad ang sample?","verdict":"best","feedback":"Answers what is answerable, refuses to guess on the regulated details, commits to a time, and keeps the conversation moving with a question."},{"text":"Mga 6 months po siguro, at oo may FDA po kami. Vegetable oil po.","verdict":"poor","feedback":"Three guesses about shelf life, regulatory status, and ingredients. This is the single most dangerous thing an agent can do."},{"text":"Sa post po lahat ng info ma’am.","verdict":"poor","feedback":"Dismissive to the most engaged lead you will get all week."}]}]'::jsonb, array['Never guess on shelf life, ingredients, or permits.', 'Group answers.', 'Close even while a question is pending.']::text[], 'published'),
  ('6eccf069-3cd8-50e5-ae98-f6a31e1eac8f', 'funny-customer-steering', 'Everything Is a Joke', 'chat', 'funny', 'intermediate', 'A friendly lead who jokes about everything and never quite answers a question.', 'Match the warmth, then steer back to one concrete question.', '[{"id":"sc-funny-t1","customer":"Kangkong chips? Baka maging kalabaw ako niyan hahaha 🤣","choices":[{"text":"Hahaha promise po, tao pa rin kayo after 😄 Pero seryoso po - balak niyo po bang ibenta or for personal lang?","verdict":"best","feedback":"Matches the energy in one line, then redirects with a single clear question."},{"text":"Hindi po, ligtas po yan, vegetable lang naman po.","verdict":"poor","feedback":"Answering a joke literally kills the rapport they were offering you."},{"text":"HAHAHA good one po! 🤣🤣🤣 Ako din po nung una akala ko ganun din 😂😂","verdict":"poor","feedback":"Over-matching the joke costs you the thread. Warmth is a bridge to the question, not the destination."}]}]'::jsonb, array['Laugh briefly, then redirect.', 'One question at a time.', 'Do not become the comedian.']::text[], 'published'),
  ('f144e6a3-a0c2-5874-a949-5c6417380bc0', 'sleepy-customer-energy', 'Low Energy on the Line', 'phone', 'sleepy', 'foundation', 'The lead answers in single syllables and sounds like they just woke up.', 'Keep it short, raise your own energy slightly, and get one clear commitment.', '[{"id":"sc-sleepy-t1","customer":"Mm... oo... ano nga ulit yun?","choices":[{"text":"Sorry po for the disturbance! Ito lang po - yung inquiry niyo sa KCO reseller pack. Mas okay po ba kung tawagan ko kayo mamaya ng hapon?","verdict":"best","feedback":"Recognises the moment, restates the purpose in one line, and offers a better time rather than pushing through."},{"text":"[repeats the full pitch from the beginning, slowly]","verdict":"poor","feedback":"A longer pitch into low attention gets absorbed even less. Shorten, do not slow down."},{"text":"Yung Kangkong Chips po, gusto niyo po ba mag-order?","verdict":"ok","feedback":"Short is right, but closing on someone who is barely awake produces a \"yes\" that evaporates by afternoon."}]}]'::jsonb, array['Do not mirror low energy.', 'Shorter sentences.', 'Offer a callback rather than pushing.']::text[], 'published')
on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  channel = excluded.channel,
  personality = excluded.personality,
  difficulty = excluded.difficulty,
  setup = excluded.setup,
  goal = excluded.goal,
  turns = excluded.turns,
  coaching = excluded.coaching,
  status = excluded.status
;


-- ---------------------------------------------------------------------------
-- Objection handling library
-- ---------------------------------------------------------------------------

insert into public.objections (id, slug, objection, translation, category, frequency, acknowledge, clarify, address, close, pitfalls, claim_sensitive, status) values
  ('fecc843b-fd49-5368-88af-e5779ad46d90', 'mahal-naman', 'Mahal naman.', 'That is expensive.', 'price', 'very-high', 'I understand po. Importante talaga na sulit ang bawat piso, especially kung negosyo ang pag-uusapan.', 'May I ask - mahal po ba compared sa budget niyo ngayon, or compared sa ibang supplier na nakita niyo?', 'Kung budget po ang concern: ang starter pack ang pinakamaliit na order namin, kaya mababa ang unang commitment niyo. Kung comparison po sa iba: ang presyo namin ay kasama na ang delivery sa Metro Manila, ang packaging na ready for resale, at ang marketing materials na pwede niyo agad gamitin. Hindi lang po chips ang binabayaran niyo - kasama na ang support para makapagsimula kayo.', 'Gusto niyo po bang i-compute natin ang per-pack cost para makita niyo kung saan papasok ang selling price niyo?', array['Do not immediately offer a discount - you probably cannot authorise it, and it teaches the customer to wait for one.', 'Do not argue that it is "not expensive". You are telling them their judgement is wrong.', 'Do not compare KCO to a named competitor.']::text[], false, 'published'),
  ('fd48a10b-38f0-5a4e-b488-e479ba86c8da', 'baka-hindi-ko-mabenta', 'Baka hindi ko mabenta.', 'I might not be able to sell it.', 'risk', 'very-high', 'Valid po yan, Ms. Rivera. Normal lang mag-alala sa unang order - ayaw naman po natin ma-stuck kayo sa stock.', 'May I ask po - ano ang mas kinakabahan niyo, ang paghahanap ng buyers or ang dami ng stock?', 'Dahil dyan po kami nag-set ng mababang minimum. Sa starter pack, sapat lang po para ma-test niyo kung aling flavour ang mabilis mauubos sa area niyo, hindi yung malaking stock na mahirap ilipat. Bibigyan din po namin kayo ng product photos, captions, at basic selling guide para hindi kayo magsimula sa zero. At kung nauubos po agad, mabilis lang ang resupply.', 'Gusto niyo po bang simulan natin sa pinakamaliit na pack, para test muna, then dagdagan natin pag okay na?', array['Never promise that the stock will definitely sell.', 'Do not dismiss the fear - it is the most reasonable objection on this list.', 'Do not push a larger pack to hit a quota.']::text[], false, 'published'),
  ('315b45b1-161e-5b43-acd9-99bfd0936d49', 'pag-isipan-ko-muna', 'Pag-isipan ko muna.', 'Let me think about it first.', 'timing', 'very-high', 'Of course po - dapat lang na pag-isipan ang anumang investment. Take your time.', 'May I ask lang po, para matulungan ko kayo - ano pong part ang pinag-iisipan niyo? Yung presyo, yung pagbebenta, or kailangan niyo pang kausapin ang partner niyo?', 'Kung presyo po: pwede natin i-break down ang cost per pack. Kung pagbebenta po: may guide kami kung paano magsimula online. Kung may kausapin pa po kayo, i-send ko na lang ang complete details para may maipakita kayo - kasama na ang inclusions at delivery schedule.', 'I-send ko po ang details ngayon. Pwede po ba akong mag-follow up bukas ng hapon para sagutin ang mga tanong niyo?', array['Do not ask "why?" bluntly - it reads as a challenge.', 'Do not invent urgency ("last stock na po") that is not real.', 'Do not ask for the sale again in the same breath.']::text[], false, 'published'),
  ('8e8db757-b563-53e2-ae43-5d4fa226eaed', 'wala-akong-experience', 'Wala akong experience sa negosyo.', 'I have no business experience.', 'capability', 'high', 'Naiintindihan ko po. Marami sa mga reseller namin ay first-timers din nung nagsimula sila.', 'May I ask po - nakapag-sell na po ba kayo online kahit personal items lang, or talagang first time?', 'Hindi po kailangan ng business background para dito. Ang binibigay namin ay ang produkto, ang product photos, ready-to-use captions, at isang simpleng guide kung paano mag-post at sumagot sa tanong ng customer. Ang kailangan lang po sa umpisa ay isang Facebook account at willingness mag-reply sa mga tanong. Meron din po kaming reseller support kung may hindi kayo sigurado.', 'Gusto niyo po bang i-send ko yung starter guide para makita niyo mismo kung gaano kasimple ang proseso?', array['Do not say "madali lang yan" - it minimises a real worry.', 'Do not promise hand-holding that the team cannot actually deliver.']::text[], false, 'published'),
  ('a7a05acd-29f0-5fe0-acc9-cbcfde0cde99', 'wala-akong-physical-store', 'Wala akong physical store.', 'I do not have a physical store.', 'capability', 'high', 'Okay lang po yan - hindi po requirement ang physical store para maging KCO reseller.', 'May I ask po - active po ba kayo sa Facebook or Messenger? Yun po ang pinakamadaling simulan.', 'Malaking parte po ng mga reseller namin ay online lang - Facebook posts, Messenger orders, at meet-up or delivery. Walang rent, walang display shelf. Bibigyan po namin kayo ng photos at captions na pwede niyo agad i-post, at may packaging na kayang i-ship. Kung may sari-sari store naman po ang kakilala niyo, pwede rin kayo mag-supply sa kanila.', 'Gusto niyo po bang i-set up natin ang online starter pack para sa inyo?', array['Do not imply an online seller is a lesser reseller.', 'Do not promise delivery coverage you have not checked.']::text[], false, 'published'),
  ('6f440cc5-80e7-5af6-9da1-51f4f0fe02ba', 'marami-nang-nagbebenta', 'Marami nang nagbebenta ng Kangkong Chips.', 'A lot of people already sell Kangkong Chips.', 'competition', 'high', 'Tama po kayo - sumikat talaga ang kangkong chips, kaya marami ang nag-offer.', 'May I ask po - nakita niyo po ba kung ano ang binebenta nila sa area niyo, at magkano?', 'Dalawa po ang pinag-iba namin. Isa, ang produkto: consistent ang crunch at packaging namin, at may proper labeling - hindi repacked. Dalawa, ang support: bibigyan namin kayo ng marketing materials at reseller pricing na hindi lang basta paubos ng stock. Ang mataas na demand po ay hindi problema - ibig sabihin may market na. Ang mahalaga ay kayo ang may maayos na supply at presentation.', 'Gusto niyo po bang ipakita ko ang product photos at packaging namin para makita niyo ang difference?', array['Never disparage a named competitor or another reseller.', 'Do not claim exclusivity or territory rights unless Admin has confirmed them in writing.']::text[], false, 'published'),
  ('9b39b6e7-6215-507b-a029-c2b9a77151e9', 'may-supplier-na-ako', 'May supplier na ako.', 'I already have a supplier.', 'competition', 'medium', 'Mabuti po yan - ibig sabihin alam niyo na ang proseso ng pag-resupply.', 'May I ask po - kumusta ang supply nila, consistent po ba ang stock at delivery?', 'Hindi po namin kailangang palitan ang supplier niyo agad. Ang ginagawa ng ibang reseller ay ginagamit kami as backup - pag out of stock sila or delayed ang delivery, may mapupuntahan kayo agad. Kung mas okay naman po ang terms namin sa tagal ng panahon, kayo na po ang magdedesisyon. Walang exclusivity requirement po sa amin.', 'Gusto niyo po bang i-send ko ang pricing namin para may comparison kayo, kahit for reference lang muna?', array['Do not ask them to break an existing agreement.', 'Do not ask who their supplier is - it reads as intelligence-gathering.', 'Do not undercut with a price you cannot honour.']::text[], false, 'published'),
  ('c80de4cb-fab2-57d5-bb62-03d5a22235d9', 'wala-akong-malaking-capital', 'Wala akong malaking capital.', 'I do not have a lot of capital.', 'capital', 'very-high', 'Naiintindihan ko po. Hindi po biro ang maglabas ng pera para sa panibagong negosyo.', 'May I ask po - magkano ang comfortable niyong ilabas sa unang order, para makita natin kung kasya?', 'Dahil dyan po ang starter pack ang pinakamababang entry namin - yun po ang minimum na order, hindi yung malaking bulk. Ganun din po ang dahilan kung bakit kasama na ang delivery sa Metro Manila, para walang dagdag na gastos sa umpisa. Wala rin pong franchise fee, membership fee, o bayad sa marketing materials.', 'Gusto niyo po bang tignan natin ang exact na halaga ng starter pack, para malaman niyo kung kasya sa budget niyo ngayon?', array['Never suggest borrowing money or offering a loan.', 'Do not present the purchase as risk-free.', 'Do not quote an instalment scheme unless Finance has approved one in writing.']::text[], false, 'published'),
  ('41f54951-85f1-5286-ad51-64327bbf37b1', 'baka-matagal-ang-roi', 'Baka matagal ang ROI.', 'The return on investment might take a long time.', 'risk', 'medium', 'Magandang tanong po - dapat lang alam niyo kung kailan bumabalik ang pera niyo.', 'May I ask po - ilan ang customer na kayang maabot niyo sa isang linggo, at gaano kadalas kayo makakapag-post?', 'Maging prangka po tayo: depende po ito sa selling price na ilalagay niyo, sa area niyo, at kung gaano kadalas kayo mag-post o mag-alok. Hindi po namin kayang mangako ng specific na panahon. Ang kaya po naming gawin ay tulungan kayong makuha ang tamang selling price at bigyan kayo ng materials para mas mabilis mag-move ang stock. Kung gusto niyo po, i-compute natin ang break-even base sa sarili niyong numbers - pero example lang po ito, hindi guarantee.', 'Gusto niyo po bang i-compute natin nang sabay ang break-even base sa target selling price niyo?', array['Never state or imply a guaranteed payback period.', 'Never quote a "typical" ROI figure that Admin has not approved.', 'Always label any computation as an illustration built from the customer’s own assumptions.']::text[], true, 'published'),
  ('8eb3fbc6-e118-59c8-8123-950b37a8d595', 'hindi-ako-marunong-mag-online-selling', 'Hindi ako marunong mag-online selling.', 'I do not know how to sell online.', 'capability', 'high', 'Okay lang po yan. Marami sa nagsisimula ay ganun din - natutunan lang nila habang nag-post.', 'May I ask po - gumagamit po ba kayo ng Facebook or Messenger sa araw-araw?', 'Kung marunong po kayong mag-post at mag-reply sa Messenger, sapat na po yun para makapagsimula. Bibigyan po namin kayo ng ready na product photos, captions na pwede niyong kopyahin, at simpleng guide kung paano sagutin ang mga karaniwang tanong - presyo, delivery, at flavour. Hindi po kailangan ng website, ads, o technical na kaalaman sa umpisa.', 'Gusto niyo po bang i-send ko yung starter kit ng photos at captions para makita niyo?', array['Do not overwhelm them with ads, SEO, or marketplace jargon.', 'Do not promise training sessions that do not exist.']::text[], false, 'published'),
  ('50ab0508-be11-5f21-b717-5d1916a93ba8', 'baka-hindi-patok-sa-lugar-namin', 'Baka hindi patok sa lugar namin.', 'It might not be popular in our area.', 'market', 'medium', 'Fair po yan - magkaiba talaga ang nagpapatok sa bawat lugar.', 'May I ask po - saan po banda kayo, at ano ang uso pong snack sa area niyo ngayon?', 'Ang pinakamurang paraan po para malaman ay maliit na test order. Yun ang dahilan kung bakit mababa ang minimum namin - para hindi kayo mag-commit sa malaking stock bago malaman kung tatanggapin sa area niyo. Nakakatulong din po na healthier snack ang positioning ng kangkong chips, kaya kadalasan may market sa mga school, office, at sari-sari store. Pero test order po ang magsasabi, hindi ang assumption natin.', 'Gusto niyo po bang simulan sa isang starter pack as test para sa area niyo?', array['Do not claim the product "always sells" anywhere.', 'Do not cite sales figures from another area as a promise.']::text[], true, 'published'),
  ('e0697753-afa6-523c-b813-32e9abc65179', 'magkano-ang-kita-ko', 'Magkano ang kita ko?', 'How much will I earn?', 'price', 'very-high', 'Magandang tanong po - dapat lang malinaw ito bago kayo mag-order.', 'May I ask po - magkano ang balak niyong ipagbenta per pack sa area niyo?', 'Ang kita po ay ang pagitan ng reseller price niyo at ng selling price na ilalagay niyo, less ang gastos niyo sa delivery o packaging. Ibibigay po namin ang exact reseller price at ang suggested retail range, pero kayo po ang magdedesisyon sa final selling price niyo. Hindi po namin kayang mangako ng specific na kita - nakadepende po ito sa presyo niyo, sa dami ng mabebenta, at sa area niyo.', 'Gusto niyo po bang i-compute natin ang margin base sa selling price na naiisip niyo, para may malinaw kayong number?', array['Never guarantee an income figure, monthly or otherwise.', 'Never repeat another reseller’s earnings as an expected result.', 'Always frame computations as the customer’s own numbers, clearly marked as an example.']::text[], true, 'published')
on conflict (id) do update set
  slug = excluded.slug,
  objection = excluded.objection,
  translation = excluded.translation,
  category = excluded.category,
  frequency = excluded.frequency,
  acknowledge = excluded.acknowledge,
  clarify = excluded.clarify,
  address = excluded.address,
  close = excluded.close,
  pitfalls = excluded.pitfalls,
  claim_sensitive = excluded.claim_sensitive,
  status = excluded.status
;


-- ---------------------------------------------------------------------------
-- Script library - 22 scripts extracted from the source material
