-- ---------------------------------------------------------------------------
-- Professional wording - avoid / use pairs
-- ---------------------------------------------------------------------------

insert into public.wording_pairs (id, avoid, use, context, note, tags, sort_order, status) values
  ('dd50b65a-2c0a-5f9a-9af3-b9470ff946c7', 'Wait lang.', 'May I ask you to hold for a moment?', 'phone', 'Always ask, never instruct.', array['hold']::text[], 0, 'published'),
  ('672a589f-8563-559b-969c-590c5a93bfb8', 'Hindi ko alam.', 'Let me verify that for you.', 'both', 'Add a time commitment: "…and I will come back to you within the hour."', array['accuracy']::text[], 1, 'published'),
  ('60a00429-a14e-5826-a085-951d4f1aafca', 'Di ko gets.', 'May I clarify what you mean?', 'both', '', array['clarify']::text[], 2, 'published'),
  ('22ac3281-7578-558e-8467-8813d9bb8fe9', 'Ha? Ano po?', 'I am sorry, could you repeat that please?', 'phone', '', array['clarify']::text[], 3, 'published'),
  ('ec8bd791-5b1a-5f75-b631-4d216a3f6836', 'Wala kami niyan.', 'That variant is not available right now - may I suggest an alternative?', 'both', '', array['stock']::text[], 4, 'published'),
  ('5cb30692-5e0a-5861-af8d-db33592ee0db', 'Sige, bye.', 'Thank you for your time, Ms. Rivera. Have a good day!', 'phone', '', array['closing']::text[], 5, 'published'),
  ('7cf650e8-19d6-56da-a089-e667986c6996', 'Hindi pwede yan.', 'What I can do for you instead is…', 'both', 'Always follow a no with an alternative.', array['boundaries']::text[], 6, 'published'),
  ('2cdf3b1c-2668-56fe-ada5-43450574331b', 'Mali kayo.', 'Let me check the details so we are looking at the same information.', 'both', '', array['conflict']::text[], 7, 'published'),
  ('24f37894-ba34-5475-9f0b-dc0c03bc39ac', 'Bakit hindi niyo binasa?', 'Let me walk you through that part again.', 'both', '', array['conflict']::text[], 8, 'published'),
  ('3c905dec-9631-5337-9470-845cce6471be', 'Kelangan niyo mag-decide na.', 'Would you like me to reserve one while you decide?', 'both', '', array['closing']::text[], 9, 'published'),
  ('edd8ee67-8d7e-5206-bc20-74b12518673d', 'Yan na po ang pinakamura.', 'That is our reseller price, and it already includes delivery within Metro Manila.', 'both', '', array['price']::text[], 10, 'published'),
  ('41228b02-579c-5dcd-a670-63aa9e6dec41', 'ok po sure', 'Sure po! 😊', 'chat', '', array['tone']::text[], 11, 'published'),
  ('51910982-3245-5a74-883e-a31afaecf2ad', 'wla po eh', 'Wala pa po sa ngayon, but restock is next week.', 'chat', '', array['stock']::text[], 12, 'published'),
  ('dafef794-0a50-5a1e-8760-0f70b6617072', 'thnx po', 'Thank you po!', 'chat', '', array['tone']::text[], 13, 'published'),
  ('64399f02-9d8f-575f-a216-1bc7a62dae02', 'sry d ko alam', 'Let me verify that for you po.', 'chat', '', array['accuracy']::text[], 14, 'published'),
  ('fa284f42-c973-5ed7-a103-67ba41d08537', 'Sino ba kausap niyo dati?', 'Let me read the conversation so you do not have to repeat yourself.', 'chat', '', array['handover']::text[], 15, 'published'),
  ('6b0a3a3a-ff41-5013-b4fe-2e5431846933', 'Sabi na sa post eh.', 'Yes po, and to make it clearer - here are the details again.', 'chat', '', array['conflict']::text[], 16, 'published'),
  ('6557a5c8-850d-5ded-8ae6-19b74110c6da', 'Bili na po kayo.', 'Gusto niyo po bang i-reserve ko para sa Friday delivery?', 'chat', '', array['closing']::text[], 17, 'published'),
  ('40a4c24d-ff5d-5acf-8762-34e22675ef78', 'Sure na po yan kikita kayo.', 'Ang kita po ay depende sa selling price at area niyo - pwede natin i-compute base sa numbers niyo.', 'both', 'Never guarantee earnings. See the objection card "Magkano ang kita ko?".', array['claims']::text[], 18, 'published'),
  ('a1ea9f13-c4c7-5fbe-b709-2222927802ce', 'Last stock na po!', 'Limited po ang natitira sa batch na ito - gusto niyo po bang i-hold ko para sa inyo?', 'both', 'Only if it is actually true. False urgency is prohibited.', array['claims']::text[], 19, 'published'),
  ('70199edc-b4a7-53f4-a793-d8322ceb9f9b', 'Ay sorry, na-forget ko.', 'Apologies for the delay - here is the update I promised.', 'both', '', array['tone']::text[], 20, 'published'),
  ('424847ed-27f4-54e5-894f-e3104cd4da0c', 'Tawag na lang po kayo ulit.', 'I will call you back at 4 PM today - is that convenient?', 'phone', 'The agent owns the callback, never the customer.', array['callback']::text[], 21, 'published'),
  ('4f6ac077-49c6-5c96-8d43-74a535142ba1', 'Ganun talaga.', 'I understand that is frustrating. Here is what I can do.', 'both', '', array['complaints']::text[], 22, 'published'),
  ('a32e6c97-d54b-5930-9958-d7e471c7c98b', 'Fault yun ng courier.', 'I am sorry this happened. I am filing it with our logistics team today.', 'both', 'Never blame a third party by name.', array['complaints']::text[], 23, 'published'),
  ('a21f2b6d-202d-54fc-add9-dd6047adcf1b', 'Magkano budget mo?', 'May I ask what budget range you are comfortable with?', 'both', '', array['discovery']::text[], 24, 'published'),
  ('a06cbeb7-b508-5be7-9712-71035d62696b', 'Hindi po namin yan ginagawa.', 'That is outside what I can approve - let me check with my team lead and come back to you.', 'both', '', array['escalation']::text[], 25, 'published')
on conflict (id) do update set
  avoid = excluded.avoid,
  use = excluded.use,
  context = excluded.context,
  note = excluded.note,
  tags = excluded.tags,
  sort_order = excluded.sort_order,
  status = excluded.status
;


-- ---------------------------------------------------------------------------
-- Quick reference cards
-- ---------------------------------------------------------------------------

insert into public.quick_reference_items (id, slug, title, kicker, kind, channel, blocks, sort_order, status) values
  ('0fca40e6-c788-5bdb-82a8-ddf93732d2bf', 'phone-opening', 'Phone Opening', 'The first seven seconds', 'script', 'phone', '[{"id":"qr-po-b1","type":"script","language":"mixed","lines":["Good morning! This is Jason from KCO Kangkong Chips.","Am I speaking with Ms. Rivera?","I am following up on your inquiry about becoming a KCO reseller.","Is now a good time for a quick two-minute call?"]},{"id":"qr-po-b2","type":"checklist","items":[{"text":"Time of day"},{"text":"Your name"},{"text":"Full company name"},{"text":"Confirm the person"},{"text":"One-sentence purpose"},{"text":"Ask for their time"}]}]'::jsonb, 0, 'published'),
  ('3363d68f-a3c0-5ced-b05b-c2dc6e44cd9f', 'chat-opening', 'Chat Opening', 'Reply within two minutes', 'script', 'chat', '[{"id":"qr-co-b1","type":"script","language":"mixed","lines":["Hi po! Good afternoon 😊","Thank you for messaging KCO Kangkong Chips.","This is Jason - how may I help you today?"]},{"id":"qr-co-b2","type":"callout","variant":"info","title":"Then ask before you send","text":"Are you planning to sell online, sa physical store, or for personal use? One question before any details go out."}]'::jsonb, 1, 'published'),
  ('91b41ac2-9819-5443-bc0f-38175217acbb', 'sales-call-structure', 'Sales Call Structure', 'Eight steps, in order', 'formula', 'phone', '[{"id":"qr-cs-b1","type":"formula","name":"8-Step Sales Call","steps":[{"key":"1","label":"Greet","detail":"Time of day, name, KCO Kangkong Chips."},{"key":"2","label":"Introduce","detail":"Confirm the person and your role."},{"key":"3","label":"Purpose","detail":"One sentence, then ask for their time."},{"key":"4","label":"Discover","detail":"Three to four questions."},{"key":"5","label":"Present","detail":"One package, tied to their answers."},{"key":"6","label":"Handle Objection","detail":"A.C.A.C."},{"key":"7","label":"Close","detail":"Specific, small, dated."},{"key":"8","label":"Confirm + End","detail":"Recap, next step, thank them."}]}]'::jsonb, 2, 'published'),
  ('6503d1f8-90b7-5a5d-b6ca-8c38a36c0896', 'kco-chat-formula', 'KCO Chat Formula', 'G.A.L.P.H.C.F.R.', 'formula', 'chat', '[{"id":"qr-cf-b1","type":"formula","name":"G.A.L.P.H.C.F.R.","steps":[{"key":"G","label":"Greet","detail":"Name, thanks, warmth."},{"key":"A","label":"Ask","detail":"One qualifying question first."},{"key":"L","label":"Listen","detail":"Answer everything they asked."},{"key":"P","label":"Present","detail":"One package, their words."},{"key":"H","label":"Handle","detail":"A.C.A.C. in writing."},{"key":"C","label":"Close","detail":"Specific and dated."},{"key":"F","label":"Follow Up","detail":"Two maximum, each adds value."},{"key":"R","label":"Report","detail":"Log the outcome."}]}]'::jsonb, 3, 'published'),
  ('b8600687-2270-5821-bb70-1d2503155901', 'acac-objection-formula', 'A.C.A.C. Objection Formula', 'Works on all twelve objections', 'formula', 'both', '[{"id":"qr-acac-b1","type":"formula","name":"A.C.A.C.","steps":[{"key":"A","label":"Acknowledge","detail":"Validate the concern in one sentence."},{"key":"C","label":"Clarify","detail":"One question to find the real version of it."},{"key":"A","label":"Address","detail":"Answer that specific concern only."},{"key":"C","label":"Close","detail":"Return to a small, dated next step."}]},{"id":"qr-acac-b2","type":"callout","variant":"warning","title":"Clarify is the step people skip","text":"Without it you answer the generic objection instead of theirs."}]'::jsonb, 4, 'published'),
  ('6a27a907-1ce9-5f51-ab54-c86163de42f5', 'order-confirmation', 'Order Confirmation', 'Eight fields, every time', 'checklist', 'both', '[{"id":"qr-oc-b1","type":"checklist","items":[{"text":"Item and flavour"},{"text":"Quantity"},{"text":"Total amount"},{"text":"Delivery date"},{"text":"Payment method"},{"text":"Complete delivery address"},{"text":"Contact number"},{"text":"Explicit \"tama po ba?\" confirmation"}]},{"id":"qr-oc-b2","type":"script","label":"Send as one message they can screenshot","language":"mixed","lines":["Confirming your order po 😊","Item: Kangkong Chips - Original","Quantity: 50 packs","Total: ₱10,000","Delivery: Friday, Metro Manila","Payment: Cash on delivery","Tama po ba lahat?"]}]'::jsonb, 5, 'published'),
  ('231b77d5-a6aa-56ca-acbf-9f8e1f9b1855', 'complaint-handling', 'Complaint Handling', 'Acknowledge → Apologise → Act → Follow up', 'checklist', 'both', '[{"id":"qr-cp-b1","type":"numbered","items":["Let them finish. Defend nothing.","Acknowledge the specific problem in their words.","Apologise for the experience, not for unverified fault.","State what you will do and by when.","Follow up when you said you would."]},{"id":"qr-cp-b2","type":"dosdonts","dos":["Ask for a photo early","Give a reference number","Keep every promised follow-up"],"donts":["Emoji in a complaint thread","Blame the courier by name","Promise a refund you cannot approve","Go silent while waiting"]}]'::jsonb, 6, 'published'),
  ('96781659-78da-5ef4-aa93-0f0d3603a8ee', 'closing-scripts', 'Closing Scripts', 'Specific, small, dated', 'script', 'both', '[{"id":"qr-cl-b1","type":"comparison","caption":"Swap the weak close for the clear one","columns":["Weak","Clear"],"rows":[["Let me know po if interested.","Shall I reserve a starter pack for Friday delivery?"],["I will send details.","I will send it now - can I call you at 4 PM to confirm?"],["Sige, think about it.","Which works better, Friday or Monday delivery?"],["Interested po ba kayo?","I will hold one pack for you until tomorrow - okay po ba?"]]},{"id":"qr-cl-b2","type":"callout","variant":"success","title":"Then stop talking","text":"After you ask, stay quiet. Filling the silence yourself is how a close becomes a discount."}]'::jsonb, 7, 'published'),
  ('dabf3c29-7747-5166-a768-d6938e189ae1', 'professional-wording', 'Professional Wording', 'The full swap library', 'rule', 'both', '[{"id":"qr-w-b1","type":"wording","pairs":[{"avoid":"Wait lang.","use":"May I ask you to hold for a moment?"},{"avoid":"Hindi ko alam.","use":"Let me verify that for you."},{"avoid":"Di ko gets.","use":"May I clarify what you mean?"},{"avoid":"Hindi pwede yan.","use":"What I can do for you instead is…"},{"avoid":"Ganun talaga.","use":"I understand that is frustrating. Here is what I can do."}]},{"id":"qr-w-b2","type":"text","text":"The searchable library of all 26 swaps lives in Learning → Professional Wording, and in the wording search on this page."}]'::jsonb, 8, 'published'),
  ('dc551208-c799-55b8-8106-8968520c71dc', 'golden-rules', 'Golden Rules', 'The two sentences that decide everything else', 'rule', 'both', '[{"id":"qr-gr-b1","type":"quote","text":"Don''t just sound like a salesperson. Sound like a professional who genuinely wants to help.","attribution":"Sales Calls"},{"id":"qr-gr-b2","type":"quote","text":"Don''t just reply to the customer. Guide the customer toward the right solution.","attribution":"Chat Support"},{"id":"qr-gr-b3","type":"callout","variant":"danger","title":"And the hard rule","text":"Never guarantee earnings, a payback period, or that stock will sell. Never invent a product fact. Never promise what you cannot authorise."}]'::jsonb, 9, 'published')
on conflict (id) do update set
